const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const z2=n=>String(n).padStart(2,'0');
const dkey=(d=new Date())=>{d=new Date(d);return d.getFullYear()+'-'+z2(d.getMonth()+1)+'-'+z2(d.getDate())};
const pick=a=>a[Math.floor(Math.random()*a.length)];
const fmtDate=d=>new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const fmtTime=d=>new Date(d).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});
const fmtDT=d=>{const x=new Date(d);return (dkey(x)===dkey()?'Today':fmtDate(x))+' · '+fmtTime(x)};
function tookTxt(a,b){const s=Math.max(0,(new Date(b)-new Date(a))/1000);const d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);return 'It took you '+(d?`${d} day${d===1?'':'s'}${h?` ${h} hr`:''}`:h?`${h} hr${m?` ${m} min`:''}`:m?`${m} min`:'less than a minute')}
const fmtDur=s=>{s=Math.max(0,Math.floor(s));const h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;return (h?h+':'+z2(m):m)+':'+z2(x)};
