function deepMerge(d,s){if(!s||typeof s!=='object'||Array.isArray(s))return s===undefined?d:s;const o={...d};for(const k in s){o[k]=(d&&typeof d[k]==='object'&&d[k]&&!Array.isArray(d[k]))?deepMerge(d[k],s[k]):s[k]}return o}
let S;
function load(){try{const raw=localStorage.getItem(KEY);return raw?deepMerge(defaults(),JSON.parse(raw)):defaults()}catch(e){return defaults()}}
let saveWarned=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){if(!saveWarned){saveWarned=true;toast('⚠️ Could not save: your browser storage is full or turned off. Try removing some photos.')}}}
