/* ============ UI helpers ============ */
function toast(msg,ms=3200){const w=$('#toasts');while(w.children.length>=3)w.firstChild.remove();const t=document.createElement('div');t.className='toast';t.innerHTML=msg;w.appendChild(t);setTimeout(()=>{t.style.transition='opacity .4s';t.style.opacity=0;setTimeout(()=>t.remove(),400)},ms)}
function modal(html,{onClose}={}){const bg=document.createElement('div');bg.className='modalbg';bg.innerHTML=`<div class="modal">${html}</div>`;bg.addEventListener('click',e=>{if(e.target===bg)closeModal()});$('#layer').appendChild(bg);bg._onClose=onClose;return bg.firstChild}
function closeModal(){const all=document.querySelectorAll('.modalbg');const m=all[all.length-1];if(m){m._onClose&&m._onClose();m.remove()}}
function confirmBox(msg,yes,{ok='Yes',danger=false}={}){modal(`<h2>${msg}</h2><div class="row" style="justify-content:flex-end;margin-top:14px"><button class="btn ghost" onclick="closeModal()">Cancel</button><button class="btn ${danger?'danger':''}" id="cfOk">${ok}</button></div>`);$('#cfOk').onclick=()=>{closeModal();yes()}}
function readImage(file,max=1000,q=.75){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const k=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=img.width*k;c.height=img.height*k;c.getContext('2d').drawImage(img,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',q))};img.onerror=rej;img.src=r.result};r.onerror=rej;r.readAsDataURL(file)})}
function filePick(cb,accept='image/*'){const i=document.createElement('input');i.type='file';i.accept=accept;i.onchange=()=>i.files[0]&&cb(i.files[0]);i.click()}
let audioCtx;function beep(freq=660,dur=.18,vol=.15,type='sine'){try{audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.value=vol;o.connect(g);g.connect(audioCtx.destination);o.start();g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+dur);o.stop(audioCtx.currentTime+dur+.05)}catch(e){}}
function chime(){beep(523,.25);setTimeout(()=>beep(659,.25),180);setTimeout(()=>beep(784,.4),360)}
function alarm(){let n=0;const iv=setInterval(()=>{beep(880,.2,.2,'square');setTimeout(()=>beep(660,.2,.2,'square'),220);if(++n>=4)clearInterval(iv)},600)}

/* speech */
function voiceFor(lang){try{const vs=speechSynthesis.getVoices();if(lang==='fil')return vs.find(v=>/^(fil|tl)/i.test(v.lang))||vs.find(v=>/Filipino|Tagalog/i.test(v.name))||vs.find(v=>/^en/i.test(v.lang));return vs.find(v=>/^en/i.test(v.lang))}catch(e){return null}}
function speak(text,lang='en',onend){try{if(!('speechSynthesis' in window)){onend&&setTimeout(onend,Math.min(6000,text.length*55));return false}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text.replace(/[\u{1F300}-\u{1FAFF}☀-➿]/gu,''));const v=voiceFor(lang);if(v)u.voice=v;u.lang=lang==='fil'?(v&&v.lang)||'fil-PH':'en-US';u.rate=.95;u.pitch=1.05;let done=false;const fin=()=>{if(!done){done=true;onend&&onend()}};u.onend=fin;u.onerror=fin;speechSynthesis.speak(u);setTimeout(fin,Math.max(4000,text.length*95));return true}catch(e){onend&&setTimeout(onend,3000);return false}}
try{speechSynthesis.getVoices();speechSynthesis.onvoiceschanged=()=>{}}catch(e){}

/* crypto */
async function hash(s){try{const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('lumi:'+s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}catch(e){let h=5381;for(const c of 'lumi:'+s)h=((h<<5)+h+c.charCodeAt(0))|0;return 'h'+h}}
const b64=buf=>btoa(String.fromCharCode(...new Uint8Array(buf)));
const unb64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));

/* ============ Derived stats ============ */
function posted(){return S.entries.filter(e=>!e.deleted).sort((a,b)=>new Date(b.date)-new Date(a.date))}
function streak(){const days=new Set(posted().map(e=>dkey(e.date)));let d=new Date();if(!days.has(dkey(d)))d.setDate(d.getDate()-1);let n=0;while(days.has(dkey(d))){n++;d.setDate(d.getDate()-1)}return n}
function moodWeather(){const r=posted().filter(e=>daysBetween(e.date,new Date())<7);if(!r.length)return{e:'🌫️',l:'No data yet',f:'Wala pang datos',avg:0};const avg=r.reduce((s,e)=>s+moodOf(e.mood).v,0)/r.length;
 const w=avg>=4.4?['☀️','Sunny','Maaraw']:avg>=3.7?['🌤️','Mostly sunny','Medyo maaraw']:avg>=3?['⛅','Partly cloudy','Maulap-ulap']:avg>=2.3?['🌧️','Rainy','Maulan']:['⛈️','Stormy','Bagyo'];return{e:w[0],l:w[1],f:w[2],avg}}
function capsulesLocked(){return S.letters.filter(l=>new Date(l.unlock)>new Date()).length}
function todayEntry(){return posted().find(e=>dkey(e.date)===dkey())}
