/* ============ Milky Way canvas ============ */
const Stars=(()=>{const c=$('#stars'),x=c.getContext('2d');let W,H,st=[],t=0,on=true,raf;
 function resize(){W=c.width=innerWidth*devicePixelRatio;H=c.height=innerHeight*devicePixelRatio;c.style.width=innerWidth+'px';c.style.height=innerHeight+'px';st=[];
  const n=Math.min(900,Math.floor(W*H/2600));for(let i=0;i<n;i++){const band=Math.random()<.55;let px,py;
   if(band){const u=Math.random();px=u*W;const center=H*.85-u*H*.7;py=center+(Math.random()+Math.random()+Math.random()-1.5)*H*.13}else{px=Math.random()*W;py=Math.random()*H}
   st.push({x:px,y:py,r:Math.random()*1.3*devicePixelRatio+.2,p:Math.random()*6.28,s:.5+Math.random()*2,c:pick(['255,255,255','200,210,255','255,225,240','220,200,255'])})}}
 function neb(){const g=x.createLinearGradient(0,H,W,0);g.addColorStop(0,'rgba(0,0,0,0)');g.addColorStop(.35,'rgba(120,80,200,.10)');g.addColorStop(.5,'rgba(230,170,255,.16)');g.addColorStop(.65,'rgba(90,120,230,.10)');g.addColorStop(1,'rgba(0,0,0,0)');
  x.save();x.globalCompositeOperation='lighter';for(let i=0;i<5;i++){const u=(i+.5)/5,cx=u*W,cy=H*.85-u*H*.7;const rg=x.createRadialGradient(cx,cy,0,cx,cy,H*.28);rg.addColorStop(0,`rgba(${i%2?'190,140,255':'140,170,255'},.10)`);rg.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=rg;x.fillRect(0,0,W,H)}
  x.fillStyle=g;x.fillRect(0,0,W,H);x.restore()}
 function frame(){t+=.016;x.clearRect(0,0,W,H);neb();const drift=Math.sin(t*.05)*6;for(const s of st){const a=.35+.65*Math.abs(Math.sin(s.p+t*s.s));x.fillStyle=`rgba(${s.c},${a})`;x.beginPath();x.arc(s.x+drift,s.y,s.r,0,6.283);x.fill()}
  if(Math.random()<.006){shoot.push({x:Math.random()*W,y:Math.random()*H*.4,l:1})}
  shoot.forEach(s=>{x.strokeStyle=`rgba(255,255,255,${s.l})`;x.lineWidth=2;x.beginPath();x.moveTo(s.x,s.y);x.lineTo(s.x-60,s.y-30);x.stroke();s.x+=14;s.y+=7;s.l-=.03});shoot=shoot.filter(s=>s.l>0);
  if(on)raf=requestAnimationFrame(frame)}
 let shoot=[];addEventListener('resize',resize);resize();
 return{show(v){c.style.display=v?'block':'none';if(v&&!on){on=true;frame()}else if(!v){on=false;cancelAnimationFrame(raf)}},start(){frame()}}})();
Stars.start();

