function applyTheme(){const st=S.settings,th=THEMES[st.style]||THEMES.galaxy;const b=document.body;
 const dark=st.dark;b.classList.toggle('light',!dark);b.classList.toggle('dark',dark);
 const acc=st.accent||th.acc;document.documentElement.style.setProperty('--accent',acc);document.documentElement.style.setProperty('--accent2',lighten(acc));
 document.documentElement.style.setProperty('--font',`'${st.font}',${st.font==='Fira Code'?'monospace':'sans-serif'}`);document.documentElement.style.setProperty('--fs',(st.font==='Press Start 2P'?Math.max(11,st.size-4):st.size)+'px');
 const bg=$('#bg');if(st.customBg){bg.style.background=`linear-gradient(rgba(0,0,0,${dark?.45:.15}),rgba(0,0,0,${dark?.45:.15})),url(${st.customBg}) center/cover`}else if(st.bgColor){bg.style.background=st.bgColor}else bg.style.background=th.bg;
 Stars.show(!st.customBg&&!st.bgColor&&(th.stars||currentScreen==='welcome'));
 const p=$('#bgPattern');p.innerHTML='';if(th.p&&!st.customBg&&!st.bgColor){const items=[...th.p.matchAll(/(\p{Extended_Pictographic}️?|<\/>|\{\}|01|;|=>|#)/gu)].map(m=>m[0]);for(let i=0;i<26;i++){const s=document.createElement('span');s.textContent=pick(items);s.style.left=Math.random()*100+'%';s.style.top=Math.random()*100+'%';s.style.fontSize=(16+Math.random()*26)+'px';s.style.animationDelay=(-Math.random()*9)+'s';if(th.mono){s.style.color='#22c55e';s.style.fontFamily='Fira Code,monospace'}p.appendChild(s)}}}
function lighten(hex){try{const n=parseInt(hex.slice(1),16);let r=n>>16,g=n>>8&255,b=n&255;r=Math.round(r+(255-r)*.45);g=Math.round(g+(255-g)*.45);b=Math.round(b+(255-b)*.45);return `rgb(${r},${g},${b})`}catch(e){return hex}}

