function render_themes(){const st=S.settings;setMain(`<div class="card"><h3>🎨 Style</h3><div class="grid3">${Object.entries(THEMES).map(([k,t])=>`<button class="theme ${st.style===k&&!st.customBg&&!st.bgColor?'on':''}" style="background:${t.bg}" onclick="setStyle('${k}')"><span class="em">${t.em}</span><span style="${k==='minimal'||k==='cute'?'color:#333;text-shadow:none':''}">${t.n}</span></button>`).join('')}</div></div>
 <div class="card"><h3>🖼️ Your own background</h3>${st.customBg?`<div class="photo"><img src="${st.customBg}" style="max-height:160px"><button class="x" onclick="S.settings.customBg=null;save();applyTheme();render()">✕</button></div>`:''}<button class="btn ghost block" style="margin-top:8px" onclick="filePick(async f=>{S.settings.customBg=await readImage(f,1400,.7);save();applyTheme();render()})">📷 ${st.customBg?'Replace':'Choose from gallery'}</button></div>
 <div class="card"><h3>🎯 Accent color</h3><div class="row">${ACCENTS.map(c=>`<button class="swatch ${(st.accent||THEMES[st.style].acc)===c?'on':''}" style="background:${c}" onclick="S.settings.accent='${c}';save();applyTheme();render()"></button>`).join('')}<input type="color" value="${st.accent||THEMES[st.style].acc}" onchange="S.settings.accent=this.value;save();applyTheme();render()" style="width:36px;height:36px;border:0;background:none"></div></div>
 <div class="card"><h3>🔤 Font and text size</h3><div class="grid2">${FONTS.map(f=>`<button class="chip ${st.font===f[0]?'on':''}" style="font-family:'${f[0]}';justify-content:center;${f[0]==='Press Start 2P'?'font-size:.6em':''}" onclick="S.settings.font='${f[0]}';save();applyTheme();render()">${f[1]}</button>`).join('')}</div>
  <label class="l">Text size: <b id="fsv">${st.size}px</b></label><input type="range" min="13" max="21" value="${st.size}" style="width:100%;accent-color:var(--accent)" oninput="S.settings.size=+this.value;$('#fsv').textContent=this.value+'px';applyTheme()" onchange="save()"></div>
 <div class="card"><div class="setrow"><div class="t"><b>🌙 Dark mode</b></div><button class="switch ${st.dark?'on':''}" onclick="S.settings.dark=!S.settings.dark;save();applyTheme();render()"></button></div>
  <div class="setrow"><div class="t"><b>🎨 Background color</b><div class="tiny muted">One solid color instead of a theme</div></div><input type="color" value="${st.bgColor||'#1e1b4b'}" onchange="S.settings.bgColor=this.value;save();applyTheme();render()" style="width:40px;height:34px;border:0;background:none">${st.bgColor?`<button class="chip" onclick="S.settings.bgColor=null;save();applyTheme();render()">Reset</button>`:''}</div></div>`)}
function setStyle(k){const t=THEMES[k];S.settings.style=k;S.settings.customBg=null;S.settings.bgColor=null;S.settings.accent=null;S.settings.dark=!!t.dark;save();applyTheme();render()}
function render_settings(){const st=S.settings;setMain(`<div class="card"><h3>👤 Account</h3><label class="l">Name</label><div class="row" style="flex-wrap:nowrap"><input class="f" id="sN" value="${esc(S.user.name)}"><button class="btn sm" onclick="const v=$('#sN').value.trim();if(v){S.user.name=v;save();toast('✓ Updated')}">Save</button></div><div class="small muted" style="margin-top:8px">📧 ${esc(S.user.email)}</div><button class="btn ghost sm" style="margin-top:10px" onclick="changePw()">🔑 Change password</button></div>
 <div class="card"><h3>🔐 Security</h3><div class="setrow"><div class="t"><b>🔢 PIN lock</b><div class="tiny muted">${S.pin?'On':'Off'}</div></div><button class="btn sm ${S.pin?'ghost':''}" onclick="setPin()">${S.pin?'Change':'Set'}</button>${S.pin?`<button class="btn ghost sm" onclick="confirmBox('Remove your PIN?',()=>{S.pin=null;S.bio=null;save();render()})">✕</button>`:''}</div>
  <div class="setrow"><div class="t"><b>🫆 Fingerprint</b><div class="tiny muted" id="bioTxt">${S.bio?'On':'Checking if supported...'}</div></div><button class="switch ${S.bio?'on':''}" onclick="${S.bio?'S.bio=null;save();render()':'enableBio()'}"></button></div>
  <div class="setrow"><div class="t"><b>🔒 Lock when returning to the app</b><div class="tiny muted">After 1 minute away</div></div><button class="switch ${st.privacy.lockOnReturn?'on':''}" onclick="S.settings.privacy.lockOnReturn=!S.settings.privacy.lockOnReturn;save();render()"></button></div></div>
 <div class="card"><h3>⏰ Rest reminders</h3><div class="setrow"><div class="t"><b>Reminder and alarm</b><div class="tiny muted">Reminder at 30 minutes, alarm at 1 hour, with a 5-minute rest mode</div></div><button class="switch ${st.rest?'on':''}" onclick="S.settings.rest=!S.settings.rest;save();render()"></button></div><div class="setrow"><div class="t"><b>🕐 Show clock</b><div class="tiny muted">The time on the top bar. Reminders still work when it's hidden.</div></div><button class="switch ${st.showTimer!==false?'on':''}" onclick="setTimerVisible(!(S.settings.showTimer!==false))"></button></div><button class="btn ghost sm" style="margin-top:8px" onclick="startRest()">🌿 Try rest mode</button></div>
 <div class="card"><h3>🔔 Notifications</h3><div class="setrow"><div class="t"><b>Daily diary reminder</b><div class="tiny muted">Shows while the app is open</div></div><input type="time" class="f" style="width:auto;padding:6px 8px" value="${st.notif.time}" onchange="S.settings.notif.time=this.value;S.lastNotif='';save()"><button class="switch ${st.notif.daily?'on':''}" onclick="S.settings.notif.daily=!S.settings.notif.daily;save();render()"></button></div>
  <div class="setrow"><div class="t"><b>Streak alerts</b></div><button class="switch ${st.notif.streak?'on':''}" onclick="S.settings.notif.streak=!S.settings.notif.streak;save();render()"></button></div>
  <div class="setrow"><div class="t"><b>Wellness tips</b></div><button class="switch ${st.notif.tips?'on':''}" onclick="S.settings.notif.tips=!S.settings.notif.tips;save();render()"></button></div></div>
 <div class="card"><h3>🛡️ Privacy</h3><div class="setrow"><div class="t"><b>Blur diary previews</b><div class="tiny muted">On Home and lists; hover or tap to reveal</div></div><button class="switch ${st.privacy.blur?'on':''}" onclick="S.settings.privacy.blur=!S.settings.privacy.blur;save();render()"></button></div>
  <div class="setrow"><div class="t"><b>🗑️ Delete all data</b><div class="tiny muted">Including the account on this device</div></div><button class="btn danger sm" onclick="confirmBox('Delete ALL data and your account? This cannot be undone.',()=>{try{localStorage.removeItem(KEY)}catch(e){}S=defaults();save();unlocked=false;$('#fab')&&$('#fab').remove();showWelcome()},{danger:true,ok:'Delete all'})">Delete</button></div></div>
 <div class="card"><h3>🌐 Language</h3><div class="row"><button class="chip ${st.lang==='en'?'on':''}" onclick="S.settings.lang='en';save();enterApp(true)">English</button><button class="chip ${st.lang==='fil'?'on':''}" onclick="S.settings.lang='fil';save();enterApp(true)">Filipino</button></div><p class="tiny muted">Note: only part of the app is translated when you change the language.</p></div>
 <button class="btn ghost block" onclick="go('themes')">🎨 Themes and appearance</button>
 <div class="card small muted"><b>⚠️ Limitations</b><ul style="padding-left:18px;line-height:1.6;margin:6px 0 0"><li>Data is saved only in this browser/device and won't move to other devices.</li><li>The AI is rule-based, not a real AI model, and is not a substitute for professional help.</li><li>The demos are animations, not real videos.</li><li>Family verification is a preview only (it needs a server).</li><li>Changing the Language doesn't translate the whole app yet.</li></ul></div>`);
 if(!S.bio)bioAvailable().then(v=>{const t=$('#bioTxt');if(t)t.textContent=v?'Supported on your device':'Not supported on this device/browser'})}
function setPin(){let step=1,first='';const m=modal(`<h2>🔢 ${S.pin?'New':'Create a'} PIN<span class="sp"></span><button class="iconbtn" onclick="closeModal()">✕</button></h2><p class="small muted center" id="spT">Enter a 4-digit PIN</p><input class="f" id="spI" inputmode="numeric" maxlength="4" type="password" style="text-align:center;font-size:2em;letter-spacing:.5em" autofocus><button class="btn block" style="margin-top:12px" id="spG">Next</button>`);
 const go2=async()=>{const v=$('#spI').value;if(!/^\d{4}$/.test(v))return toast('Use exactly 4 digits.');if(step===1){first=v;step=2;$('#spT').textContent='Re-enter your PIN';$('#spI').value='';$('#spG').textContent='Save'}else{if(v!==first){toast('PINs don\'t match. Try again.');step=1;$('#spT').textContent='Enter a 4-digit PIN';$('#spI').value='';return}S.pin=await hash('pin'+v);save();closeModal();toast('🔢 PIN set!');render()}};$('#spG').onclick=go2;$('#spI').onkeydown=e=>{if(e.key==='Enter')go2()}}
function changePw(){modal(`<h2>🔑 Change password<span class="sp"></span><button class="iconbtn" onclick="closeModal()">✕</button></h2><input class="f" type="password" id="op" placeholder="Current password"><input class="f" type="password" id="np" style="margin-top:8px" placeholder="New password (8+ characters)"><input class="f" type="password" id="np2" style="margin-top:8px" placeholder="Re-enter new password"><button class="btn block" style="margin-top:12px" id="cpG">Save</button>`);
 $('#cpG').onclick=async()=>{if((await hash($('#op').value))!==S.user.pass)return toast('Current password is incorrect.');const n=$('#np').value;if(n.length<8)return toast('Use at least 8 characters.');if(n!==$('#np2').value)return toast('Passwords don\'t match.');S.user.pass=await hash(n);save();closeModal();toast('🔑 Password changed!')}}


/* ================= BUCKET LIST ================= */
const CATS=[['travel','✈️','Travel and Places','#38bdf8'],['personal','🌱','Personal Goals','#4ade80'],['love','💕','Love and Relationships','#f472b6'],['family','👨‍👩‍👧','Family Moments','#fb923c'],['adventure','🧗','Adventures','#f97316'],['career','🎓','Career and Education','#a78bfa'],['food','🍜','Food and Experiences','#facc15'],['finance','💰','Financial Goals','#22c55e'],['hobby','🎨','Hobbies and Skills','#ec4899'],['simple','🌼','Simple Life Moments','#fcd34d']];
const allCats=()=>[...CATS,...(S.cats||[]).map(c=>[c.k,c.e,c.n,c.c])];
const catOf=k=>allCats().find(c=>c[0]===k)||['other','⭐','Other','#94a3b8'];
const STATUS={not:['⚪','Not Started','#94a3b8'],plan:['📝','Planning','#60a5fa'],prog:['🚀','In Progress','#f59e0b'],done:['✅','Completed','#22c55e']};
const PRIO={high:['🔴','High','#ef4444',3],med:['🟠','Medium','#f59e0b',2],low:['🟢','Low','#22c55e',1]};
const IDEAS=[['See the northern lights','travel'],['Learn to swim','hobby'],['Watch a sunrise at Mayon Volcano','travel'],['Swim with whale sharks in Donsol','adventure'],['Write a letter to my parents','family'],['Save my first ₱50,000','finance'],['Learn to play the guitar','hobby'],['Go on a solo trip','travel'],['Try 10 new street foods','food'],['Plant a tree','simple'],['Read 12 books in a year','personal'],['Run a 5K','personal'],['Cook a full meal for my family','family'],['Go camping under the stars','adventure'],['Learn a new language','career'],['Visit Batanes','travel'],['Watch a concert of my favorite artist','simple'],['Take a family photo shoot','family'],['Go island hopping in Palawan','travel'],['Start a small business','finance'],['Learn to drive','personal'],['Volunteer for a community project','simple'],['Bake a cake from scratch','food'],['Climb a mountain','adventure'],['Graduate with honors','career'],['Go on a road trip with friends','adventure'],['Learn basic coding','career'],['Visit Japan in cherry blossom season','travel'],['Try surfing in Siargao','adventure'],['Have a picnic by the beach','love'],['Write my own song','hobby'],['Open a savings account','finance'],['Watch the sunset with someone special','love'],['Learn photography','hobby'],['Spend a day without my phone','simple'],['Get a professional certificate','career'],['Eat at a fine-dining restaurant','food'],['Ride a hot air balloon','adventure'],['Make a scrapbook of my year','simple'],['Visit all the provinces of Bicol','travel']];
const dreams=()=>S.dreams||[];
const dStat=()=>{const d=dreams();return{total:d.length,done:d.filter(x=>x.status==='done').length,ongoing:d.filter(x=>x.status==='plan'||x.status==='prog').length,pending:d.filter(x=>x.status==='not').length}};
const monthKey=(d=new Date())=>{d=new Date(d);return d.getFullYear()+'-'+z2(d.getMonth()+1)};
function logAct(ic,t){S.activity=S.activity||[];S.activity.unshift({ic,t,ts:new Date().toISOString()});S.activity=S.activity.slice(0,60)}
function daysLeft(d){return d?daysBetween(new Date(),d+'T12:00'):null}
function countdownTxt(x){if(x.status==='done')return`✅ ${fmtDate(x.completedAt)}`;if(!x.target)return'No target date';const n=daysLeft(x.target);return n>1?`⏳ ${n} days left`:n===1?'⏳ Tomorrow!':n===0?'🎯 Today!':`⚠️ ${-n} day${n===-1?'':'s'} overdue`}
function confetti(){const em=['🎉','✨','🌟','🎊','💖','🪣'];for(let i=0;i<36;i++){const s=document.createElement('div');s.textContent=pick(em);s.style.cssText=`position:fixed;z-index:120;left:${50+(Math.random()-.5)*20}%;top:55%;font-size:${16+Math.random()*18}px;pointer-events:none;transition:transform 1.4s cubic-bezier(.2,.8,.3,1),opacity 1.4s`;document.body.appendChild(s);requestAnimationFrame(()=>{s.style.transform=`translate(${(Math.random()-.5)*360}px,${-200-Math.random()*300}px) rotate(${Math.random()*720}deg)`;s.style.opacity=0});setTimeout(()=>s.remove(),1500)}}
async function saveFile(filename,data){try{if(window.claude&&claude.use){const d=await claude.use('downloads');if(d){try{await d.save({filename,data});toast('⬇️ Saved '+esc(filename));return true}catch(e){if(e&&e.code==='declined'){toast('Download cancelled.');return true}if(e&&e.code==='rate_limited'){toast('Please wait a moment, then try again.');return true}}}}}catch(e){}
 try{const a=document.createElement('a');a.href=URL.createObjectURL(data instanceof Blob?data:new Blob([data]));a.download=filename;document.body.appendChild(a);a.click();a.remove();if(!window.claude){toast('⬇️ Saved '+esc(filename));return true}}catch(e){}return false}

/* ---------- Dashboard ---------- */
function dreamOfMonth(){const mk=monthKey();const open=dreams().filter(x=>x.status!=='done');if(S.dotm&&S.dotm.m===mk&&dreams().some(x=>x.id===S.dotm.id))return dreams().find(x=>x.id===S.dotm.id);if(!open.length)return null;
 const sorted=[...open].sort((a,b)=>(PRIO[b.priority]?.[3]||0)-(PRIO[a.priority]?.[3]||0)||(a.target||'9').localeCompare(b.target||'9'));const top=sorted.slice(0,Math.min(3,sorted.length));const d=top[(new Date().getMonth())%top.length];S.dotm={m:mk,id:d.id};save();return d}
function nextCountdown(){return dreams().filter(x=>x.status!=='done'&&x.target&&daysLeft(x.target)>=0).sort((a,b)=>a.target.localeCompare(b.target))[0]}
function dailyIdea(){const i=(Math.floor(Date.now()/864e5))%IDEAS.length;return IDEAS[i]}
function render_home(){const name=S.user.name.split(' ')[0],h=new Date().getHours();const greet=h<12?'Good morning':h<18?'Good afternoon':'Good evening';const st=dStat();const P=S.profile||{};
 const dm=dreamOfMonth(),cd=nextCountdown(),idea=dailyIdea();const recent=[...dreams()].sort((a,b)=>(b.updated||b.created).localeCompare(a.updated||a.created)).slice(0,4);
 setMain(`<div class="card" style="background:${P.banner||'linear-gradient(135deg,color-mix(in srgb,var(--accent) 55%,transparent),var(--card))'};display:flex;gap:14px;align-items:center">${avatarHTML(58)}<div style="flex:1"><div class="small" style="opacity:.85">${h<12?'🌅':h<18?'☀️':'🌙'} ${greet},</div><div style="font-size:1.5em;font-weight:700;line-height:1.2">${esc(name)}!</div><div class="small" style="opacity:.85">${st.total?`You've completed ${st.done} of ${st.total} dreams. Keep going! ✨`:'Ready to write your bucket list? ✨'}</div></div></div>
 <div class="card"><div style="font-size:1.02em;line-height:1.5;font-style:italic">“${esc(currentQuote())}”</div><div class="row" style="margin-top:10px"><span class="tiny muted" style="flex:1">💭 Daily inspiration</span><button class="chip" onclick="editQuote()">✏️</button><button class="chip" onclick="shuffleQuote()">🔀</button><button class="chip ${S.quote.mode==='daily'?'on':''}" onclick="S.quote.mode='daily';save();render()">📅</button></div></div>
 <div class="grid4">${[['🪣',st.total,'Total','all'],['✅',st.done,'Completed','done'],['🚀',st.ongoing,'Ongoing','ongoing'],['⏸️',st.pending,'Pending','not']].map(s=>`<button class="stat" onclick="dFilter.status='${s[3]}';go('dreams')"><div class="big" style="font-size:1.35em">${s[0]} ${s[1]}</div><div class="lbl">${s[2]}</div></button>`).join('')}</div>
 <div class="card"><h3>⚡ Quick add</h3><div class="row" style="flex-wrap:nowrap"><input class="f" id="qaT" placeholder="I want to..." maxlength="120"><select class="f" id="qaC" style="width:44%">${allCats().map(c=>`<option value="${c[0]}">${c[1]} ${c[2]}</option>`).join('')}</select></div><div class="row" style="margin-top:8px"><button class="btn" style="flex:1" onclick="quickAddDream()">➕ Add to bucket list</button><button class="btn ghost" onclick="openDreamForm()">More details</button></div></div>
 ${dm?`<div class="card" style="overflow:hidden;padding:0"><div style="height:110px;background:${dm.cover?`url(${dm.cover}) center/cover`:`linear-gradient(135deg,${catOf(dm.cat)[3]},var(--accent))`};display:flex;align-items:flex-end;padding:12px"><span class="chip" style="background:rgba(0,0,0,.45);color:#fff;border:0">🌟 Dream of the Month · ${new Date().toLocaleDateString(undefined,{month:'long'})}</span></div><div style="padding:14px"><b style="font-size:1.1em">${catOf(dm.cat)[1]} ${esc(dm.title)}</b><div class="small muted" style="margin:4px 0 8px">${countdownTxt(dm)} · ${STATUS[dm.status][0]} ${STATUS[dm.status][1]}</div><div class="bar"><i style="width:${dm.progress||0}%"></i></div><div class="row" style="margin-top:10px"><button class="btn sm" onclick="openDream('${dm.id}')">Open</button><button class="btn ghost sm" onclick="chooseDOTM()">🔀 Choose another</button></div></div></div>`:''}
 ${cd?`<div class="card" style="text-align:center"><h3 style="justify-content:center">⏳ Countdown</h3><div class="small"><b>${esc(cd.title)}</b></div><div id="cdw" style="font-size:1.6em;font-weight:700;font-variant-numeric:tabular-nums;margin:6px 0"></div><div class="tiny muted">Target: ${fmtDate(cd.target+'T00:00')}</div></div>`:''}
 <div class="card"><h3>🎲 For you today</h3><div class="step"><span style="font-size:1.4em">${catOf(idea[1])[1]}</span><div style="flex:1"><div class="tiny muted">Daily dream suggestion</div><b>${esc(idea[0])}</b></div><button class="btn sm" onclick="addIdea(${IDEAS.indexOf(idea)})">➕</button></div>
  <div class="grid3" style="margin-top:8px"><button class="qa" onclick="randomPicker()"><b>🎯</b>Random picker</button><button class="qa" onclick="surpriseMe()"><b>🎁</b>Surprise me</button><button class="qa" onclick="go('challenges')"><b>🏆</b>Challenges</button></div></div>
 <div class="card"><h3>🕒 Recent bucket lists<span class="sp"></span><button class="chip" onclick="go('dreams')">See all →</button></h3>${recent.length?`<div class="list">${recent.map(dreamRow).join('')}</div>`:`<p class="small muted" style="margin:0">Your bucket list is empty. Add your first dream above! 🌠</p>`}</div>
 <div class="card"><h3>📰 Recent activities</h3>${(S.activity||[]).length?`<div class="list">${S.activity.slice(0,6).map(a=>`<div class="item"><span style="font-size:1.3em">${a.ic}</span><div style="flex:1" class="small">${esc(a.t)}<div class="tiny muted">${timeAgo(a.ts)}</div></div></div>`).join('')}</div>`:'<p class="small muted" style="margin:0">Your activity will show up here.</p>'}</div>
 <div class="grid2"><button class="card" style="margin:0;text-align:left" onclick="go('analytics')"><b>📊 Analytics</b><div class="tiny muted">Stats and yearly summary</div></button><button class="card" style="margin:0;text-align:left" onclick="go('vision')"><b>🖼️ Vision board</b><div class="tiny muted">${(S.boards||[]).length} board(s)</div></button></div>`);
 $('#qaT').onkeydown=e=>{if(e.key==='Enter')quickAddDream()};
 if(cd){const tick=()=>{const el=$('#cdw');if(!el)return;const ms=new Date(cd.target+'T00:00')-new Date();if(ms<=0){el.textContent='🎯 Today!';return}const d=Math.floor(ms/864e5),hh=Math.floor(ms%864e5/36e5),m=Math.floor(ms%36e5/6e4),s=Math.floor(ms%6e4/1e3);el.textContent=`${d}d ${z2(hh)}h ${z2(m)}m ${z2(s)}s`};tick();timers.push(setInterval(tick,1000))}}
function timeAgo(ts){const s=(Date.now()-new Date(ts))/1000;return s<60?'just now':s<3600?Math.floor(s/60)+'m ago':s<86400?Math.floor(s/3600)+'h ago':Math.floor(s/86400)+'d ago'}
function avatarHTML(sz,edit=true){const P=S.profile||{};const cam=Math.max(22,Math.round(sz*.4));return `<div style="position:relative;flex-shrink:0;width:${sz}px;height:${sz}px"><div ${edit?'onclick="avatarMenu()" role="button" title="Change profile photo"':''} style="width:100%;height:100%;border-radius:50%;cursor:${edit?'pointer':'default'};background:${P.photo?`url(${P.photo}) center/cover`:'var(--accent)'};display:grid;place-items:center;font-size:${sz*.48}px;color:#fff;font-weight:700;box-shadow:0 0 0 3px rgba(255,255,255,.35)">${P.photo?'':P.emoji?P.emoji:esc(S.user.name[0].toUpperCase())}</div>${edit?`<button onclick="event.stopPropagation();avatarMenu()" title="Change profile photo" aria-label="Change profile photo" style="position:absolute;right:-3px;bottom:-3px;width:${cam}px;height:${cam}px;border-radius:50%;background:#fff;color:#222;display:grid;place-items:center;box-shadow:0 2px 8px rgba(0,0,0,.35);border:2px solid var(--accent)"><svg viewBox="0 0 24 24" width="${Math.round(cam*.58)}" height="${Math.round(cam*.58)}" fill="none" stroke="#222" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 8h3l2-3h6l2 3h3a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1z"/><circle cx="12" cy="13" r="3.5"/></svg></button>`:''}</div>`}
function pickAvatar(){filePick(async f=>{try{const img=await readImage(f,480,.82);S.profile={...(S.profile||{}),photo:img};save();toast('📸 Profile photo updated!');closeModal();render()}catch(e){toast('Could not read that photo.')}})}
function avatarMenu(){const P=S.profile||{};if(!P.photo)return pickAvatar();modal(`<h2>Profile photo<span class="sp"></span><button class="iconbtn" onclick="closeModal()">✕</button></h2><div style="width:160px;height:160px;border-radius:50%;margin:6px auto 16px;background:url(${P.photo}) center/cover;box-shadow:0 0 0 4px var(--accent)"></div><button class="btn block" onclick="pickAvatar()">🖼️ Choose from gallery / photos</button><button class="btn ghost block" style="margin-top:8px" onclick="S.profile={...(S.profile||{}),photo:null};save();closeModal();render();toast('Profile photo removed.')">🗑️ Remove photo</button>`)}
function quickAddDream(){const t=$('#qaT').value.trim();if(!t)return toast('Type your dream first ✨');addDream({title:t,cat:$('#qaC').value});toast(`🪣 Added to your bucket list at ${fmtTime(new Date())}!`);render()}
function addIdea(i){const[t,c]=IDEAS[i];if(dreams().some(d=>d.title.toLowerCase()===t.toLowerCase()))return toast('That dream is already on your list.');addDream({title:t,cat:c});toast('🪣 Added: '+esc(t));closeModal();render()}
function addDream(o){const now=new Date().toISOString();const d={id:uid(),title:o.title,desc:o.desc||'',notes:o.notes||'',cat:o.cat||'personal',priority:o.priority||'med',status:o.status||'not',progress:o.progress||0,target:o.target||'',completedAt:null,fav:!!o.fav,cover:o.cover||null,budget:o.budget||'',location:o.location||'',country:o.country||'',refs:o.refs||[],collections:o.collections||[],created:now,updated:now};S.dreams=S.dreams||[];S.dreams.push(d);logAct('🪣',`Added “${d.title}”`);save();checkBadges();return d}
function chooseDOTM(){const open=dreams().filter(x=>x.status!=='done');modal(`<h2>🌟 Dream of the Month<span class="sp"></span><button class="iconbtn" onclick="closeModal()">✕</button></h2><div class="list">${open.map(d=>`<button class="item" style="width:100%;text-align:left" onclick="S.dotm={m:monthKey(),id:'${d.id}'};save();closeModal();render()"><span style="font-size:1.4em">${catOf(d.cat)[1]}</span><div style="flex:1">${esc(d.title)}</div>${S.dotm&&S.dotm.id===d.id?'⭐':''}</button>`).join('')}</div>`)}

/* ---------- Random picker / surprise ---------- */
function randomPicker(){const open=dreams().filter(x=>x.status!=='done');if(open.length<2)return toast('Add at least 2 unfinished dreams to use the picker.');
 modal(`<div class="center"><h2 style="justify-content:center">🎯 Random Dream Picker</h2><div id="rpBox" style="font-size:1.3em;font-weight:700;min-height:80px;display:grid;place-items:center;padding:16px;border-radius:16px;background:var(--card2);margin:10px 0">🎲</div><div id="rpAct"></div></div>`);
 let n=0;const total=22+Math.floor(Math.random()*8);let chosen;const spin=()=>{chosen=open[Math.floor(Math.random()*open.length)];const b=$('#rpBox');if(!b)return;b.textContent=catOf(chosen.cat)[1]+' '+chosen.title;beep(400+n*20,.05,.06);if(++n<total)setTimeout(spin,40+n*n*.6);else{confetti();chime();$('#rpAct').innerHTML=`<p class="small muted">The universe picked this one for you!</p><div class="row" style="justify-content:center"><button class="btn" onclick="startDream('${chosen.id}')">🚀 Let's do this!</button><button class="btn ghost" onclick="closeModal();randomPicker()">🔀 Spin again</button></div>`}};spin()}
function startDream(id){const d=dreams().find(x=>x.id===id);if(d.status==='not'){setStatus(d,'plan')}save();closeModal();openDream(id)}
function surpriseMe(){const r=Math.random();if(dreams().length&&r<.4){const d=pick(dreams());confetti();return modal(`<div class="center"><div style="font-size:3em">🎁</div><h2 style="justify-content:center">Remember this dream?</h2><div class="step" style="justify-content:center"><b>${catOf(d.cat)[1]} ${esc(d.title)}</b></div><p class="small muted">${countdownTxt(d)}</p><button class="btn" onclick="closeModal();openDream('${d.id}')">Open it</button></div>`)}
 const i=Math.floor(Math.random()*IDEAS.length),[t,c]=IDEAS[i];confetti();modal(`<div class="center"><div style="font-size:3em">🎁</div><h2 style="justify-content:center">Surprise! Try this dream</h2><div class="step" style="justify-content:center;font-size:1.1em"><b>${catOf(c)[1]} ${esc(t)}</b></div><div class="row" style="justify-content:center;margin-top:10px"><button class="btn" onclick="addIdea(${i})">➕ Add it</button><button class="btn ghost" onclick="closeModal();surpriseMe()">🔀 Another</button></div></div>`)}

/* ---------- Dreams list ---------- */
let dFilter={q:'',status:'all',cat:'all',prio:'all',fav:false,sort:'updated',view:'list'};
function filteredDreams(){let l=dreams().filter(d=>{const f=dFilter;if(f.q&&!(d.title+' '+d.desc+' '+d.notes+' '+d.location).toLowerCase().includes(f.q.toLowerCase()))return false;if(f.status==='ongoing'){if(!['plan','prog'].includes(d.status))return false}else if(f.status!=='all'&&d.status!==f.status)return false;if(f.cat!=='all'&&d.cat!==f.cat)return false;if(f.prio!=='all'&&d.priority!==f.prio)return false;if(f.fav&&!d.fav)return false;return true});
 const s=dFilter.sort;l.sort((a,b)=>s==='target'?(a.target||'9999').localeCompare(b.target||'9999'):s==='priority'?PRIO[b.priority][3]-PRIO[a.priority][3]:s==='progress'?(b.progress||0)-(a.progress||0):s==='az'?a.title.localeCompare(b.title):s==='created'?b.created.localeCompare(a.created):(b.updated||'').localeCompare(a.updated||''));return l}
function dreamRow(d){const c=catOf(d.cat);return`<button class="item" style="width:100%;text-align:left" onclick="openDream('${d.id}')"><div style="width:48px;height:48px;border-radius:12px;flex-shrink:0;background:${d.cover?`url(${d.cover}) center/cover`:c[3]};display:grid;place-items:center;font-size:1.5em">${d.cover?'':c[1]}</div><div style="flex:1;min-width:0"><div style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis"><b>${esc(d.title)}</b> ${d.fav?'❤️':''}</div><div class="tiny muted">${STATUS[d.status][0]} ${STATUS[d.status][1]} · <span style="color:${PRIO[d.priority][2]}">●</span> ${PRIO[d.priority][1]} · ${countdownTxt(d)}</div><div class="tiny muted" style="opacity:.8">🕒 ${d.status==='done'&&d.completedAt?'Done '+fmtDT(d.completedAt):'Added '+fmtDT(d.created)}</div><div class="bar" style="height:5px;margin-top:5px"><i style="width:${d.progress||0}%;background:${STATUS[d.status][2]}"></i></div></div></button>`}
function dreamCard(d){const c=catOf(d.cat);const lay=S.settings.cardLayout||'grid';
 if(lay==='compact')return`<button class="item" style="width:100%;text-align:left;padding:8px 0" onclick="openDream('${d.id}')"><span>${STATUS[d.status][0]}</span><span style="flex:1">${esc(d.title)}</span><span class="tiny muted">${d.progress||0}%</span></button>`;
 if(lay==='list')return dreamRow(d);
 return`<div class="card" style="margin:0;padding:0;overflow:hidden;cursor:pointer" onclick="openDream('${d.id}')"><div style="height:96px;position:relative;background:${d.cover?`url(${d.cover}) center/cover`:`linear-gradient(135deg,${c[3]},var(--accent))`};display:grid;place-items:center;font-size:2.4em">${d.cover?'':c[1]}<button onclick="event.stopPropagation();toggleFav('${d.id}')" style="position:absolute;top:6px;right:6px;width:30px;height:30px;border-radius:50%;background:rgba(0,0,0,.35);font-size:.45em">${d.fav?'❤️':'🤍'}</button><span style="position:absolute;top:8px;left:8px;width:10px;height:10px;border-radius:50%;background:${PRIO[d.priority][2]};box-shadow:0 0 0 2px #fff"></span></div>
 <div style="padding:10px"><b class="small" style="display:block;line-height:1.3">${esc(d.title)}</b><div class="tiny muted" style="margin:4px 0">${STATUS[d.status][0]} ${STATUS[d.status][1]}</div><div class="bar" style="height:6px"><i style="width:${d.progress||0}%;background:${STATUS[d.status][2]}"></i></div><div class="tiny muted" style="margin-top:5px">${countdownTxt(d)}</div><div class="tiny muted" style="opacity:.8">🕒 ${d.status==='done'&&d.completedAt?'Done '+fmtDT(d.completedAt):'Added '+fmtDT(d.created)}</div></div></div>`}
let dTab='list';
function render_dreams(){const tabs=`<div class="tabs">${[['list','🪣 My Bucket List'],['cats','🗂️ Categories'],['progress','📈 Progress'],['map','🗺️ Dream map']].map(t=>`<button class="${dTab===t[0]?'on':''}" onclick="dTab='${t[0]}';render()">${t[1]}</button>`).join('')}</div>`;
 if(dTab==='cats')return setMain(tabs+catsHTML());if(dTab==='progress')return setMain(tabs+progressHTML());if(dTab==='map')return setMain(tabs+dreamMapHTML());
 const f=dFilter;setMain(tabs+`<div class="row" style="flex-wrap:nowrap"><input class="f" id="dSearch" placeholder="🔎 Search bucket lists..." value="${esc(f.q)}"><button class="btn" onclick="openDreamForm()">➕</button></div>
 <div class="row" style="margin-top:8px;flex-wrap:nowrap;overflow-x:auto">
  <select class="chip" onchange="dFilter.status=this.value;render()">${[['all','All status'],['not','⚪ Not started'],['plan','📝 Planning'],['prog','🚀 In progress'],['ongoing','🔄 Ongoing'],['done','✅ Completed']].map(o=>`<option value="${o[0]}" ${f.status===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select>
  <select class="chip" onchange="dFilter.cat=this.value;render()"><option value="all">All categories</option>${allCats().map(c=>`<option value="${c[0]}" ${f.cat===c[0]?'selected':''}>${c[1]} ${c[2]}</option>`).join('')}</select>
  <select class="chip" onchange="dFilter.prio=this.value;render()">${[['all','Any priority'],['high','🔴 High'],['med','🟠 Medium'],['low','🟢 Low']].map(o=>`<option value="${o[0]}" ${f.prio===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select>
  <button class="chip ${f.fav?'on':''}" onclick="dFilter.fav=!dFilter.fav;render()" style="white-space:nowrap">❤️ Favorites (${dreams().filter(x=>x.fav).length})</button></div>
 <div class="row" style="margin-top:8px"><span class="tiny muted" style="flex:1" id="dCount"></span><select class="chip" onchange="dFilter.sort=this.value;render()">${[['updated','Recently updated'],['created','Newest'],['target','Target date'],['priority','Priority'],['progress','Progress'],['az','A–Z']].map(o=>`<option value="${o[0]}" ${f.sort===o[0]?'selected':''}>↕️ ${o[1]}</option>`).join('')}</select>
 <div class="row" style="gap:4px">${[['grid','▦'],['list','☰'],['compact','≡']].map(l=>`<button class="chip ${(S.settings.cardLayout||'grid')===l[0]?'on':''}" onclick="S.settings.cardLayout='${l[0]}';save();render()">${l[1]}</button>`).join('')}</div></div><div id="dList"></div>`);
 const draw=()=>{const l=filteredDreams();$('#dCount').textContent=`${l.length} of ${dreams().length} dreams`;const lay=S.settings.cardLayout||'grid';$('#dList').innerHTML=l.length?(lay==='grid'?`<div class="grid2" style="margin-top:8px">${l.map(dreamCard).join('')}</div>`:`<div class="card">${l.map(dreamCard).join('')}</div>`):`<div class="card center"><div style="font-size:3em">🌠</div><p class="muted">${dreams().length?'No dreams match your search or filters.':'No dreams yet. What do you want to do in this life?'}</p><button class="btn" onclick="openDreamForm()">➕ Add a dream</button>${dreams().length?' <button class="btn ghost" onclick="dFilter={...dFilter,q:\'\',status:\'all\',cat:\'all\',prio:\'all\',fav:false};render()">Clear filters</button>':''}</div>`};draw();
 const q=$('#dSearch');q.oninput=()=>{dFilter.q=q.value;draw()}}
function toggleFav(id){const d=dreams().find(x=>x.id===id);d.fav=!d.fav;d.updated=new Date().toISOString();if(d.fav)logAct('❤️',`Favorited “${d.title}”`);save();toast(d.fav?'❤️ Added to favorites':'Removed from favorites');if($('.modal'))openDream(id,true);render()}

/* ---------- Dream form ---------- */
let dForm=null;
function openDreamForm(id,preset){const d=id?dreams().find(x=>x.id===id):null;dForm=d?JSON.parse(JSON.stringify(d)):{title:'',desc:'',notes:'',cat:'personal',priority:'med',status:'not',progress:0,target:'',fav:false,cover:null,budget:'',location:'',country:'',refs:[],collections:[],...(preset||{})};closeModal();drawDreamForm(!!d)}
function drawDreamForm(edit){const f=dForm;const m=document.querySelector('.modal');if(m)closeModal();
 modal(`<h2>${edit?'✏️ Edit dream':'🪣 New bucket list'}<span class="sp"></span><button class="iconbtn" onclick="closeModal()">✕</button></h2>
 ${f.cover?`<div class="photo" style="margin-top:0"><img src="${f.cover}" style="max-height:170px"><button class="x" onclick="dfSync();dForm.cover=null;drawDreamForm(${edit})">✕</button><button class="btn sm rep" onclick="dfSync();dfCover(${edit})">🔄 Change</button></div>`:`<button class="btn ghost block" onclick="dfSync();dfCover(${edit})">🖼️ Upload cover photo</button>`}
 <label class="l">Dream title *</label><input class="f" id="fT" maxlength="120" value="${esc(f.title)}" placeholder="e.g. Watch the sunrise at Mayon Volcano">
 <label class="l">Description</label><textarea class="f" id="fD" style="min-height:70px" placeholder="What is this dream about?">${esc(f.desc)}</textarea>
 <label class="l">Personal notes</label><textarea class="f" id="fN" style="min-height:60px" placeholder="Why it matters to you, plans, reminders...">${esc(f.notes)}</textarea>
 <label class="l">Category</label><div class="row" style="flex-wrap:nowrap"><select class="f" id="fC">${allCats().map(c=>`<option value="${c[0]}" ${f.cat===c[0]?'selected':''}>${c[1]} ${c[2]}</option>`).join('')}</select><button class="btn ghost sm" onclick="dfSync();newCategory(()=>drawDreamForm(${edit}))">➕</button></div>
 <div class="grid2"><div><label class="l">Target date</label><input class="f" type="date" id="fDate" value="${f.target}"></div><div><label class="l">Estimated budget (₱)</label><input class="f" id="fB" inputmode="decimal" value="${esc(f.budget)}" placeholder="0"></div></div>
 <label class="l">Priority level</label><div class="row">${Object.entries(PRIO).map(([k,p])=>`<button class="chip ${f.priority===k?'on':''}" onclick="dfSync();dForm.priority='${k}';drawDreamForm(${edit})">${p[0]} ${p[1]}</button>`).join('')}</div>
 <label class="l">Status</label><div class="row">${Object.entries(STATUS).map(([k,s])=>`<button class="chip ${f.status===k?'on':''}" onclick="dfSync();dForm.status='${k}';if('${k}'==='done')dForm.progress=100;if('${k}'==='not'&&dForm.progress===100)dForm.progress=0;drawDreamForm(${edit})">${s[0]} ${s[1]}</button>`).join('')}</div>
 <label class="l">Progress: <b id="fPv">${f.progress}%</b></label><input type="range" id="fP" min="0" max="100" step="5" value="${f.progress}" style="width:100%;accent-color:var(--accent)" oninput="$('#fPv').textContent=this.value+'%'">
 <div class="grid2"><div><label class="l">Location</label><input class="f" id="fL" value="${esc(f.location)}" placeholder="e.g. Donsol, Sorsogon"></div><div><label class="l">Show on dream map</label><select class="f" id="fK"><option value="">None</option><option value="ph" ${f.country==='ph'?'selected':''}>Philippines</option>${DEST.map(x=>`<option value="${x.k}" ${f.country===x.k?'selected':''}>${esc(x.n)}</option>`).join('')}</select></div></div>
 <label class="l">Reference photos (${(f.refs||[]).length}/4)</label><div class="row">${(f.refs||[]).map((r,i)=>`<div style="position:relative"><img src="${r}" style="width:64px;height:64px;object-fit:cover;border-radius:10px"><button onclick="dfSync();dForm.refs.splice(${i},1);drawDreamForm(${edit})" style="position:absolute;top:-6px;right:-6px;width:22px;height:22px;border-radius:50%;background:#000a;color:#fff;font-size:.7em">✕</button></div>`).join('')}${(f.refs||[]).length<4?`<button class="iconbtn" style="width:64px;height:64px" onclick="dfSync();dfRef(${edit})">➕</button>`:''}</div>
 ${(S.collections||[]).length?`<label class="l">Collections</label><div class="row">${S.collections.map(c=>`<button class="chip ${f.collections.includes(c.id)?'on':''}" onclick="dfSync();const a=dForm.collections;a.includes('${c.id}')?a.splice(a.indexOf('${c.id}'),1):a.push('${c.id}');this.classList.toggle('on',a.includes('${c.id}'))">${c.e} ${esc(c.n)}</button>`).join('')}</div>`:''}
 <div class="setrow" style="margin-top:8px"><div class="t"><b>❤️ Mark as favorite</b></div><button type="button" class="switch ${f.fav?'on':''}" onclick="dfSync();dForm.fav=!dForm.fav;this.classList.toggle('on',dForm.fav);toast(dForm.fav?'❤️ Will be saved in your Favorites':'🤍 Removed from Favorites',1800)"></button></div>
 <button class="btn block" style="margin-top:12px" onclick="saveDreamForm()">${edit?'💾 Save changes':'🪣 Add to bucket list'}</button>`)}
function dfSync(){const g=id=>{const e=document.getElementById(id);return e?e.value:null};const f=dForm;const v={title:g('fT'),desc:g('fD'),notes:g('fN'),cat:g('fC'),target:g('fDate'),budget:g('fB'),location:g('fL'),country:g('fK')};for(const k in v)if(v[k]!==null)f[k]=v[k];const p=g('fP');if(p!==null)f.progress=+p}
function dfCover(edit){filePick(async file=>{dForm.cover=await readImage(file,1000,.72);drawDreamForm(edit)})}
function dfRef(edit){filePick(async file=>{dForm.refs.push(await readImage(file,700,.7));drawDreamForm(edit)})}
function setStatus(d,st){const was=d.status;d.status=st;if(st==='done'){d.progress=100;if(!d.completedAt)d.completedAt=new Date().toISOString()}else{d.completedAt=null;if(was==='done'&&d.progress===100)d.progress=90}d.updated=new Date().toISOString()}
function logProgress(d,from,to){if(from===to)return;S.progressLog=S.progressLog||[];S.progressLog.push({id:d.id,ts:new Date().toISOString(),from,to});S.progressLog=S.progressLog.slice(-500)}
function saveDreamForm(){dfSync();const f=dForm;f.title=f.title.trim();if(!f.title)return toast('Please add a dream title.');
 if(f.status==='done')f.progress=100;else if(f.progress===100&&f.status!=='done')f.status='done';if(f.status==='prog'&&f.progress===0)f.progress=5;
 if(f.id){const d=dreams().find(x=>x.id===f.id);const wasDone=d.status==='done',from=d.progress||0;const st=f.status;Object.assign(d,f);d.status=wasDone?'done':d.status;setStatus(d,st);logProgress(d,from,d.progress);d.updated=new Date().toISOString();logAct('✏️',`Updated “${d.title}”`);if(st==='done'&&!wasDone)celebrate(d)}
 else{const st=f.status;const d=addDream(f);if(st==='done'){d.status='not';setStatus(d,'done');celebrate(d)}logProgress(d,0,d.progress)}
 save();checkBadges();closeModal();toast(f.id?'💾 Dream updated!':'🪣 Dream added!');render()}
function celebrate(d){confetti();chime();logAct('🏁',`Completed “${d.title}”`);setTimeout(()=>modal(`<div class="center"><div style="font-size:3.5em">🏁</div><h2 style="justify-content:center">Dream completed!</h2><p><b>${esc(d.title)}</b></p><p class="small muted">Congratulations! Save the memory while it's fresh.</p><div class="row" style="justify-content:center"><button class="btn" onclick="closeModal();memPreset={dreamId:'${d.id}',cap:${JSON.stringify(d.title).replace(/"/g,'&quot;')},location:${JSON.stringify(d.location||'').replace(/"/g,'&quot;')}};memTab='add';go('memories')">📸 Add memory</button><button class="btn ghost" onclick="closeModal();journalFor('${d.id}')">📓 Write about it</button></div></div>`),500)}
function newCategory(after){modal(`<h2>➕ Custom category<span class="sp"></span><button class="iconbtn" onclick="closeModal()">✕</button></h2><div class="row" style="flex-wrap:nowrap"><input class="f" id="ncE" maxlength="4" value="⭐" style="width:70px;text-align:center;font-size:1.3em"><input class="f" id="ncN" maxlength="30" placeholder="Category name"></div><label class="l">Color</label><div class="row">${ACCENTS.map((c,i)=>`<button class="swatch ${i===0?'on':''}" data-c="${c}" style="background:${c}" onclick="document.querySelectorAll('[data-c]').forEach(x=>x.classList.remove('on'));this.classList.add('on')"></button>`).join('')}</div><button class="btn block" style="margin-top:12px" id="ncS">Save category</button>`);
 $('#ncS').onclick=()=>{const n=$('#ncN').value.trim();if(!n)return toast('Name your category.');S.cats=S.cats||[];const k='c_'+uid();S.cats.push({k,e:$('#ncE').value.trim()||'⭐',n,c:document.querySelector('[data-c].on').dataset.c});if(dForm)dForm.cat=k;save();closeModal();toast('🗂️ Category added!');after?after():render()}}
function catsHTML(){const cnt={};dreams().forEach(d=>cnt[d.cat]=(cnt[d.cat]||0)+1);
 return`<div class="grid2">${allCats().map(c=>{const n=cnt[c[0]]||0,dn=dreams().filter(d=>d.cat===c[0]&&d.status==='done').length;const custom=c[0].startsWith('c_');return`<div class="card" style="margin:0;cursor:pointer;border-left:4px solid ${c[3]}" onclick="dFilter.cat='${c[0]}';dTab='list';render()"><div class="row" style="flex-wrap:nowrap"><span style="font-size:1.8em">${c[1]}</span><span class="sp" style="flex:1"></span>${custom?`<button class="muted" onclick="event.stopPropagation();delCategory('${c[0]}')">✕</button>`:''}</div><b class="small">${esc(c[2])}</b><div class="tiny muted">${n} dream${n===1?'':'s'} · ${dn} done</div><div class="bar" style="height:5px;margin-top:6px"><i style="width:${n?dn/n*100:0}%;background:${c[3]}"></i></div></div>`}).join('')}
 <button class="card" style="margin:0;border-style:dashed;display:grid;place-items:center;min-height:110px" onclick="newCategory()"><div class="center"><div style="font-size:1.8em">➕</div><b class="small">Custom category</b></div></button></div>`}
function delCategory(k){const n=dreams().filter(d=>d.cat===k).length;confirmBox(`Delete this category?${n?` Its ${n} dream(s) will move to Personal Goals.`:''}`,()=>{S.cats=S.cats.filter(c=>c.k!==k);dreams().forEach(d=>{if(d.cat===k)d.cat='personal'});if(dFilter.cat===k)dFilter.cat='all';save();render()},{danger:true,ok:'Delete'})}

/* ---------- Dream details ---------- */
function openDream(id,re){if(re)closeModal();const d=dreams().find(x=>x.id===id);if(!d)return;const c=catOf(d.cat);const js=posted().filter(e=>e.dreamId===id),ms=(S.memories||[]).filter(m=>m.dreamId===id);const cols=(S.collections||[]).filter(x=>d.collections.includes(x.id));
 modal(`<div style="height:150px;margin:-20px -18px 12px;border-radius:24px 24px 0 0;background:${d.cover?`url(${d.cover}) center/cover`:`linear-gradient(135deg,${c[3]},var(--accent))`};position:relative;display:grid;place-items:center;font-size:3.5em">${d.cover?'':c[1]}<button class="iconbtn" style="position:absolute;font-size:16px;top:12px;right:12px;background:rgba(0,0,0,.4);color:#fff" onclick="closeModal()">✕</button><button class="iconbtn" style="position:absolute;font-size:16px;top:12px;right:56px;background:rgba(0,0,0,.4)" onclick="toggleFav('${d.id}')">${d.fav?'❤️':'🤍'}</button></div>
 <h2 style="margin-bottom:6px">${esc(d.title)}</h2><div class="row"><span class="chip" style="border-color:${c[3]}">${c[1]} ${esc(c[2])}</span><span class="chip">${STATUS[d.status][0]} ${STATUS[d.status][1]}</span><span class="chip"><span style="color:${PRIO[d.priority][2]}">●</span> ${PRIO[d.priority][1]} priority</span>${cols.map(x=>`<span class="chip">${x.e} ${esc(x.n)}</span>`).join('')}</div>
 ${d.desc?`<p style="line-height:1.6;white-space:pre-wrap">${esc(d.desc)}</p>`:''}
 <div class="card" style="margin:10px 0"><div class="row"><b style="flex:1">Progress</b><b>${d.progress||0}%</b></div><div class="bar" style="height:12px;margin:8px 0"><i style="width:${d.progress||0}%;background:${STATUS[d.status][2]}"></i></div>
  <div class="row">${d.status!=='done'?`<button class="chip" onclick="bumpProgress('${d.id}',-10)">−10%</button><button class="chip" onclick="bumpProgress('${d.id}',10)">+10%</button>`:''}${Object.entries(STATUS).map(([k,s])=>`<button class="chip ${d.status===k?'on':''}" onclick="quickStatus('${d.id}','${k}')">${s[0]}</button>`).join('')}</div></div>
 <div class="card" style="margin:10px 0">${[['⏳','Countdown',countdownTxt(d)],['🎯','Target date',d.target?fmtDate(d.target+'T12:00'):'Not set'],['🏁','Completed',d.completedAt?fmtDT(d.completedAt):'Not yet'],['💰','Estimated budget',d.budget?'₱'+Number(d.budget).toLocaleString():'Not set'],['📍','Location',d.location?esc(d.location)+(d.country?' '+(d.country==='ph'?flagHTML('ph',13):DEST.find(x=>x.k===d.country)?.f||''):''):'Not set'],['🕒','Added',fmtDT(d.created)]].map(r=>`<div class="setrow"><span class="t small">${r[0]} ${r[1]}</span><b class="small">${r[2]}</b></div>`).join('')}</div>
 ${d.notes?`<div class="card" style="margin:10px 0"><h3>📝 Personal notes</h3><div class="small" style="white-space:pre-wrap;line-height:1.6">${esc(d.notes)}</div></div>`:''}
 ${(d.refs||[]).length?`<h3 style="margin:10px 0 6px">🖼️ Reference photos</h3><div class="grid4">${d.refs.map(r=>`<img src="${r}" style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px">`).join('')}</div>`:''}
 <div class="card" style="margin:10px 0"><h3>📓 Journal entries (${js.length})<span class="sp"></span><button class="chip" onclick="closeModal();journalFor('${d.id}')">➕ Write</button></h3>${js.slice(0,5).map(e=>`<button class="item" style="width:100%;text-align:left" onclick="closeModal();viewEntry('${e.id}')"><span>${moodOf(e.mood).e}</span><div style="flex:1" class="small">${fmtDate(e.date)} · ${esc((e.text||'').slice(0,50))}</div></button>`).join('')||'<p class="tiny muted" style="margin:0">No journal entries linked yet.</p>'}</div>
 <div class="card" style="margin:10px 0"><h3>📸 Memories (${ms.length})<span class="sp"></span><button class="chip" onclick="closeModal();memPreset={dreamId:'${d.id}',cap:${JSON.stringify(d.title).replace(/"/g,'&quot;')},location:${JSON.stringify(d.location||'').replace(/"/g,'&quot;')}};memTab='add';go('memories')">➕ Add</button></h3>${ms.length?`<div class="grid4">${ms.map(m=>`<button onclick="closeModal();viewMem('${m.id}')" style="aspect-ratio:1;border-radius:10px;overflow:hidden;background:var(--card2)">${m.img?`<img src="${m.img}" style="width:100%;height:100%;object-fit:cover">`:'📝'}</button>`).join('')}</div>`:'<p class="tiny muted" style="margin:0">No memories yet.</p>'}</div>
 <div class="row" style="margin-top:6px">${d.status!=='done'?`<button class="btn" style="background:#22c55e" onclick="quickStatus('${d.id}','done')">🏁 Mark complete</button>`:''}<button class="btn ghost" onclick="openDreamForm('${d.id}')">✏️ Edit</button><button class="btn danger" onclick="delDream('${d.id}')">🗑️ Delete</button></div>`)}
function bumpProgress(id,n){const d=dreams().find(x=>x.id===id);const from=d.progress||0;d.progress=Math.max(0,Math.min(100,from+n));if(d.progress>0&&d.status==='not')d.status='prog';if(d.progress===100){setStatus(d,'done');celebrate(d)}d.updated=new Date().toISOString();logProgress(d,from,d.progress);logAct('📈',`“${d.title}” is now ${d.progress}%`);save();checkBadges();openDream(id,true);render()}
function quickStatus(id,st){const d=dreams().find(x=>x.id===id);if(d.status===st)return;const from=d.progress||0,wasDone=d.status==='done';setStatus(d,st);if(st==='prog'&&!d.progress)d.progress=10;if(st==='not')d.progress=0;logProgress(d,from,d.progress);logAct(STATUS[st][0],`“${d.title}” → ${STATUS[st][1]}`);save();checkBadges();closeModal();if(st==='done'&&!wasDone)celebrate(d);else openDream(id);render()}
function delDream(id){const d=dreams().find(x=>x.id===id);confirmBox(`Delete “${esc(d.title)}”? This can't be undone.`,()=>{S.dreams=dreams().filter(x=>x.id!==id);logAct('🗑️',`Deleted “${d.title}”`);save();closeModal();toast('🗑️ Dream deleted.');render()},{danger:true,ok:'Delete'})}

/* ---------- Progress tracker ---------- */
function monthsBack(n){return[...Array(n)].map((_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-(n-1-i));return d})}
function progressHTML(){const st=dStat();const ms=monthsBack(6);const comp=ms.map(m=>dreams().filter(d=>d.completedAt&&monthKey(d.completedAt)===monthKey(m)).length);const upd=ms.map(m=>(S.progressLog||[]).filter(p=>monthKey(p.ts)===monthKey(m)&&p.to>p.from).length);const mx=Math.max(1,...comp,...upd);
 const groups=Object.entries(STATUS).map(([k,s])=>({k,s,l:dreams().filter(d=>d.status===k)}));const avg=dreams().length?Math.round(dreams().reduce((a,d)=>a+(d.progress||0),0)/dreams().length):0;
 return`<div class="card"><h3>📈 Overall progress<span class="sp"></span><b>${avg}%</b></h3><div class="bar" style="height:14px"><i style="width:${avg}%"></i></div><div class="grid4" style="margin-top:12px">${groups.map(g=>`<div class="stat"><div class="big" style="font-size:1.3em">${g.s[0]} ${g.l.length}</div><div class="lbl">${g.s[1]}</div></div>`).join('')}</div></div>
 <div class="card"><h3>🗓️ Monthly progress tracking</h3><div style="display:flex;gap:8px;align-items:flex-end;height:130px">${ms.map((m,i)=>`<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;height:100%;justify-content:flex-end"><div class="tiny">${comp[i]||''}</div><div style="display:flex;gap:2px;align-items:flex-end;width:100%;justify-content:center"><div title="Completed" style="width:42%;height:${comp[i]/mx*90+2}px;background:#22c55e;border-radius:5px"></div><div title="Progress updates" style="width:42%;height:${upd[i]/mx*90+2}px;background:var(--accent);opacity:.7;border-radius:5px"></div></div><div class="tiny muted">${m.toLocaleDateString(undefined,{month:'short'})}</div></div>`).join('')}</div><div class="tiny muted center" style="margin-top:6px"><span style="color:#22c55e">■</span> Completed dreams &nbsp; <span style="color:var(--accent)">■</span> Progress updates</div></div>
 ${groups.filter(g=>g.l.length).map(g=>`<div class="card"><h3>${g.s[0]} ${g.s[1]} (${g.l.length})</h3>${g.l.sort((a,b)=>(a.target||'9').localeCompare(b.target||'9')).map(d=>`<button class="item" style="width:100%;text-align:left" onclick="openDream('${d.id}')"><span style="color:${PRIO[d.priority][2]}" title="${PRIO[d.priority][1]} priority">●</span><div style="flex:1;min-width:0"><div class="small" style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis"><b>${esc(d.title)}</b></div><div class="bar" style="height:5px;margin-top:4px"><i style="width:${d.progress||0}%;background:${g.s[2]}"></i></div></div><div class="tiny muted" style="text-align:right;min-width:80px">${d.progress||0}%<br>${countdownTxt(d)}</div></button>`).join('')}</div>`).join('')||'<div class="card center muted">Add dreams to track your progress.</div>'}`}

/* ---------- Dream map ---------- */
function dreamMapHTML(){const X=l=>(l+180),Y=l=>(90-l);const pts=dreams().filter(d=>d.country).map(d=>{const c=d.country==='ph'?{lat:12.88,lon:121.77,k:'ph',flag:'ph'}:DEST.find(x=>x.k===d.country);return c?{d,c}:null}).filter(Boolean);
 const favD=DEST.filter(x=>S.fav.includes(x.k)||S.wish.includes(x.k));
 return`<div class="card mapwrap" style="padding:10px"><svg viewBox="0 10 360 150">${CONT.map(p=>`<polygon points="${p.map(c=>X(c[0])+','+Y(c[1])).join(' ')}" fill="rgba(255,255,255,.22)" stroke="rgba(255,255,255,.3)" stroke-width=".5"/>`).join('')}
 ${favD.map(x=>`<g onclick="openDest('${x.k}')" style="cursor:pointer"><circle cx="${X(x.lon)}" cy="${Y(x.lat)}" r="2.4" fill="#fff" opacity=".7"/>${flagAt(x.flag||x.k,X(x.lon)-4,Y(x.lat)-10,8)}</g>`).join('')}
 ${pts.map((p,i)=>`<g onclick="openDream('${p.d.id}')" style="cursor:pointer"><circle cx="${X(p.c.lon)+(i%3-1)*3}" cy="${Y(p.c.lat)+(Math.floor(i/3)%3-1)*3}" r="3.4" fill="${STATUS[p.d.status][2]}" stroke="#fff" stroke-width="1"/></g>`).join('')}</svg>
 <p class="tiny muted center" style="margin:8px 0 0">Dots are your dreams (colored by status). Flags are saved destinations. Tap to open.</p></div>
 <div class="card"><h3>📍 Dreams on the map (${pts.length})</h3>${pts.length?`<div class="list">${pts.map(p=>dreamRow(p.d)).join('')}</div>`:'<p class="small muted" style="margin:0">Edit a dream and choose “Show on dream map” to pin it here.</p>'}<button class="btn ghost block" style="margin-top:10px" onclick="go('dest')">🌍 Explore Dream Destinations</button></div>`}

/* ---------- Dream Journal helpers ---------- */
function normCompose(c){c.photos=c.photos||(c.photo?[c.photo]:[]);delete c.photo;c.dreamId=c.dreamId||'';c.quote=c.quote||'';{const old=c.editingId?(S.entries||[]).find(x=>x.id===c.editingId):null;c.jdate=old?dkey(old.date):dkey()}return c}
function journalExtras(c){normCompose(c);const ds=dreams();
 return`${c.editingId?'<div class="chip on" style="margin-bottom:8px">✏️ Editing an entry</div>':''}<div class="row" style="margin-top:10px">${c.photos.map((p,i)=>`<div style="position:relative"><img src="${p}" style="width:76px;height:76px;object-fit:cover;border-radius:12px"><button onclick="syncText();compose.photos.splice(${i},1);render()" title="Remove" style="position:absolute;top:-6px;right:-6px;width:24px;height:24px;border-radius:50%;background:#000b;color:#fff;font-size:.75em">✕</button></div>`).join('')}${c.photos.length<4?`<button class="iconbtn" style="width:76px;height:76px;flex-direction:column;font-size:.75em" onclick="addPhoto()">📷<br>Add</button>`:''}</div>
 <div class="grid2"><div><label class="l">📅 Journal date</label><input type="hidden" id="jDate" value="${c.jdate}"><div class="jdatefix" title="The journal date is set automatically">${new Date(c.jdate+'T12:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'})}<span class="tiny muted">${c.jdate===dkey()?'Today':'Saved date'} 🔒</span></div></div><div><label class="l">🪣 Link to a dream</label><select class="f" id="jDream"><option value="">None</option>${ds.map(d=>`<option value="${d.id}" ${c.dreamId===d.id?'selected':''}>${catOf(d.cat)[1]} ${esc(d.title.slice(0,40))}</option>`).join('')}</select></div></div>
 <label class="l">✨ Inspirational quote</label><div class="row" style="flex-wrap:nowrap"><input class="f" id="jQuote" value="${esc(c.quote)}" placeholder="A quote that inspires you today"><button class="iconbtn" title="Random quote" onclick="syncText();compose.quote=pick(QUOTES);render()">🎲</button></div>`}
function journalFor(id){compose=null;initCompose();normCompose(compose);compose.dreamId=id;diaryView='write';go('diary')}
function buildEntry(c){normCompose(c);const today=c.jdate===dkey();let date;const old=c.editingId?S.entries.find(x=>x.id===c.editingId):null;
 if(old&&dkey(old.date)===c.jdate)date=old.date;else date=today?new Date().toISOString():new Date(c.jdate+'T12:00').toISOString();
 const e={id:old?old.id:uid(),date,mood:c.mood,text:c.text.trim(),photo:c.photos[0]||null,photos:c.photos,places:c.places,shared:c.shared,dreamId:c.dreamId||'',quote:(c.quote||'').trim(),edited:old?new Date().toISOString():undefined};
 if(old){Object.assign(old,e);logAct('✏️','Edited a journal entry');return old}S.entries.push(e);if(e.dreamId){const d=dreams().find(x=>x.id===e.dreamId);if(d){d.updated=new Date().toISOString();logAct('📓',`Wrote about “${d.title}”`)}}else logAct('📓','Wrote a journal entry');return e}
function editEntry(id){const e=S.entries.find(x=>x.id===id);if(!e)return;compose={mood:e.mood,text:e.text,photos:e.photos||(e.photo?[e.photo]:[]),places:[...(e.places||[])],shared:e.shared,dreamId:e.dreamId||'',quote:e.quote||'',jdate:dkey(e.date),editingId:e.id};closeModal();diaryView='write';go('diary')}
function entryPhotos(e){const ps=e.photos||(e.photo?[e.photo]:[]);if(!ps.length)return'';return ps.length===1?`<div class="photo"><img src="${ps[0]}"></div>`:`<div class="grid2" style="margin-top:10px">${ps.map(p=>`<img src="${p}" style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:12px">`).join('')}</div>`}
function entryExtras(e){const d=e.dreamId&&dreams().find(x=>x.id===e.dreamId);return`${d?`<button class="chip" style="margin-top:10px" onclick="closeModal();openDream('${d.id}')">🪣 ${esc(d.title)}</button>`:''}${e.quote?`<div class="step" style="font-style:italic;margin-top:10px">✨ “${esc(e.quote)}”</div>`:''}`}
let jq='';
function renderJournalList(tabs){setMain(tabs+`<input class="f" id="jSearch" placeholder="🔎 Search journal entries..." value="${esc(jq)}"><div class="row" style="margin-top:8px"><select class="chip" id="jDF"><option value="">All dreams</option>${dreams().map(d=>`<option value="${d.id}">${esc(d.title.slice(0,30))}</option>`).join('')}</select><span class="tiny muted" id="jCount"></span></div><div id="jList"></div>`);
 const draw=()=>{const q=jq.toLowerCase(),df=$('#jDF').value;const l=posted().filter(e=>(!q||((e.text||'')+' '+(e.quote||'')+' '+(e.places||[]).join(' ')+' '+moodOf(e.mood).l).toLowerCase().includes(q))&&(!df||e.dreamId===df));$('#jCount').textContent=l.length+' entries';$('#jList').innerHTML=entryListHTML(l)};
 $('#jSearch').oninput=e=>{jq=e.target.value;draw()};$('#jDF').onchange=draw;draw()}

/* ---------- Wishlist & Favorites ---------- */
let wlTab='fav';
function render_wishlist(){const tabs=`<div class="tabs">${[['fav','❤️ Favorites'],['col','🗂️ Collections'],['items','🛍️ Wishlist'],['travel','✈️ Travel']].map(t=>`<button class="${wlTab===t[0]?'on':''}" onclick="wlTab='${t[0]}';render()">${t[1]}</button>`).join('')}</div>`;
 if(wlTab==='fav'){const f=dreams().filter(d=>d.fav);return setMain(tabs+(f.length?`<div class="grid2">${f.map(dreamCard).join('')}</div>`:`<div class="card center"><div style="font-size:3em">❤️</div><p class="muted">Tap the heart on any dream to save it as a favorite.</p><button class="btn" onclick="go('dreams')">Browse my dreams</button></div>`))}
 if(wlTab==='col'){const C=S.collections||[];return setMain(tabs+`<div class="card"><h3>➕ New collection</h3><div class="row" style="flex-wrap:nowrap"><input class="f" id="colE" value="📁" maxlength="4" style="width:64px;text-align:center"><input class="f" id="colN" placeholder="e.g. Before I turn 25"><button class="btn" onclick="addCollection()">Add</button></div></div>
  ${C.map(c=>{const ds=dreams().filter(d=>d.collections.includes(c.id));return`<div class="card"><h3>${c.e} ${esc(c.n)} <span class="tiny muted">(${ds.length})</span><span class="sp"></span><button class="chip" onclick="pickForCollection('${c.id}')">➕ Dreams</button><button class="muted" onclick="delCollection('${c.id}')">🗑️</button></h3>${ds.length?`<div class="list">${ds.map(dreamRow).join('')}</div>`:'<p class="tiny muted" style="margin:0">Empty. Add some dreams.</p>'}</div>`}).join('')||'<div class="card center muted small">Group your dreams into collections like “Summer 2027” or “With my family”.</div>'}`)}
 if(wlTab==='items'){const I=S.wishItems||[];const tot=I.filter(i=>!i.got).reduce((s,i)=>s+(+i.budget||0),0);return setMain(tabs+`<div class="card"><h3>🛍️ Add a wishlist item</h3><input class="f" id="wiT" placeholder="e.g. Film camera"><div class="grid2" style="margin-top:8px"><input class="f" id="wiB" inputmode="decimal" placeholder="Estimated budget (₱)"><select class="f" id="wiD"><option value="">Link to dream (optional)</option>${dreams().map(d=>`<option value="${d.id}">${esc(d.title.slice(0,30))}</option>`).join('')}</select></div><div class="row" style="margin-top:8px"><button class="btn ghost" id="wiP" onclick="wiPhoto()">${wiDraftPhoto?'✅ Photo added':'📷 Reference photo'}</button><button class="btn" style="flex:1" onclick="addWishItem()">➕ Add item</button></div></div>
  <div class="card"><h3>📋 My wishlist<span class="sp"></span><span class="small">Total: <b>₱${tot.toLocaleString()}</b></span></h3>${I.length?`<div class="list">${I.map(i=>{const d=i.dreamId&&dreams().find(x=>x.id===i.dreamId);return`<div class="item"><button class="switch ${i.got?'on':''}" style="width:26px;height:26px;border-radius:8px" onclick="togWish2('${i.id}')"></button>${i.photo?`<img src="${i.photo}" style="width:46px;height:46px;border-radius:10px;object-fit:cover">`:'<span style="font-size:1.5em">🎁</span>'}<div style="flex:1;${i.got?'opacity:.5;text-decoration:line-through':''}"><b class="small">${esc(i.t)}</b><div class="tiny muted">${i.budget?'₱'+Number(i.budget).toLocaleString():'No budget'}${d?' · 🪣 '+esc(d.title):''}</div></div><button class="muted" onclick="S.wishItems=S.wishItems.filter(x=>x.id!=='${i.id}');save();render()">✕</button></div>`}).join('')}</div>`:'<p class="small muted" style="margin:0">No items yet.</p>'}</div>`)}
 const tr=dreams().filter(d=>d.cat==='travel');const saved=DEST.filter(x=>S.fav.includes(x.k)||S.wish.includes(x.k));
 setMain(tabs+`<div class="card"><h3>✈️ Travel dreams (${tr.length})<span class="sp"></span><button class="chip" onclick="openDreamForm(null,{cat:'travel'})">➕</button></h3>${tr.length?`<div class="list">${tr.map(dreamRow).join('')}</div>`:'<p class="small muted" style="margin:0">No travel dreams yet.</p>'}</div>
 <div class="card"><h3>🌍 Saved dream destinations (${saved.length})</h3>${saved.length?`<div class="list">${saved.map(x=>`<button class="item" style="width:100%;text-align:left" onclick="openDest('${x.k}')"><span style="font-size:1.6em">${x.f}</span><div style="flex:1"><b>${x.n}</b><div class="tiny muted">${S.fav.includes(x.k)?'❤️ Favorite ':''}${S.wish.includes(x.k)?'📝 Wishlist':''}${S.travelGoals[x.k]?' · 🎯 '+fmtDate(S.travelGoals[x.k]):''}</div></div>›</button>`).join('')}</div>`:'<p class="small muted" style="margin:0">Save countries from Dream Destinations.</p>'}<button class="btn ghost block" style="margin-top:10px" onclick="go('dest')">🌍 Open Dream Destinations</button></div>`)}
let wiDraftPhoto=null;function wiPhoto(){filePick(async f=>{wiDraftPhoto=await readImage(f,600,.7);const b=$('#wiP');if(b)b.textContent='✅ Photo added'})}
function addWishItem(){const t=$('#wiT').value.trim();if(!t)return toast('Name your wishlist item.');S.wishItems=S.wishItems||[];S.wishItems.unshift({id:uid(),t,budget:$('#wiB').value.replace(/[^\d.]/g,''),dreamId:$('#wiD').value,photo:wiDraftPhoto,got:false});wiDraftPhoto=null;logAct('🛍️',`Added wishlist item “${t}”`);save();render()}
function togWish2(id){const i=S.wishItems.find(x=>x.id===id);i.got=!i.got;if(i.got){chime();toast('🎉 Got it!')}save();render()}
function addCollection(){const n=$('#colN').value.trim();if(!n)return toast('Name your collection.');S.collections=S.collections||[];S.collections.push({id:uid(),n,e:$('#colE').value.trim()||'📁'});save();checkBadges();render()}
function delCollection(id){confirmBox('Delete this collection? Your dreams will stay.',()=>{S.collections=S.collections.filter(c=>c.id!==id);dreams().forEach(d=>d.collections=d.collections.filter(x=>x!==id));save();render()},{danger:true,ok:'Delete'})}
function pickForCollection(cid){const c=S.collections.find(x=>x.id===cid);modal(`<h2>${c.e} ${esc(c.n)}<span class="sp"></span><button class="iconbtn" onclick="closeModal();render()">✕</button></h2>${dreams().length?`<div class="list">${dreams().map(d=>`<div class="item"><span style="flex:1">${catOf(d.cat)[1]} ${esc(d.title)}</span><button class="switch ${d.collections.includes(cid)?'on':''}" onclick="const d=dreams().find(x=>x.id==='${d.id}');d.collections.includes('${cid}')?d.collections.splice(d.collections.indexOf('${cid}'),1):d.collections.push('${cid}');save();this.classList.toggle('on')"></button></div>`).join('')}</div>`:'<p class="muted">Add some dreams first.</p>'}<button class="btn block" style="margin-top:12px" onclick="closeModal();render()">Done</button>`,{onClose:()=>render()})}
function destToDream(k){const x=DEST.find(d=>d.k===k);if(dreams().some(d=>d.country===k&&d.cat==='travel'))return toast('This destination is already in your bucket list.');addDream({title:`Visit ${x.n}`,cat:'travel',country:k,location:x.cap+', '+x.n,target:S.travelGoals[k]||'',desc:x.d});toast(`🪣 “Visit ${x.n}” added to your bucket list!`)}

/* ---------- Vision boards ---------- */
let vbId=null;
const VB_BG=['linear-gradient(135deg,#fbcfe8,#ddd6fe)','linear-gradient(135deg,#bae6fd,#bbf7d0)','linear-gradient(135deg,#fde68a,#fecaca)','linear-gradient(160deg,#1e1b4b,#4c1d95)','linear-gradient(160deg,#0f172a,#334155)','#fffaf0'];
function render_vision(){const B=S.boards||[];const b=B.find(x=>x.id===vbId);if(!b){vbId=null;return setMain(`<div class="card"><h3>🖼️ Create a vision board</h3><div class="row" style="flex-wrap:nowrap"><input class="f" id="vbN" placeholder="e.g. My 2027 Vision"><button class="btn" onclick="addBoard()">Create</button></div></div>
 ${B.length?`<div class="grid2">${B.map(x=>`<button class="card" style="margin:0;padding:0;overflow:hidden;text-align:left" onclick="vbId='${x.id}';render()"><div style="height:100px;background:${x.bg};display:grid;grid-template-columns:repeat(3,1fr);gap:2px;padding:4px">${x.items.slice(0,6).map(i=>i.type==='img'?`<div style="background:url(${i.src}) center/cover;border-radius:4px"></div>`:`<div style="background:rgba(255,255,255,.6);border-radius:4px;font-size:.5em;padding:2px;color:#333;overflow:hidden">${esc(i.text.slice(0,30))}</div>`).join('')}</div><div style="padding:10px"><b class="small">${esc(x.name)}</b><div class="tiny muted">${x.items.length} items · ${x.layout}</div></div></button>`).join('')}</div>`:'<div class="card center"><div style="font-size:3em">🖼️</div><p class="muted">Collect images, quotes and goals that inspire you in one place.</p></div>'}`)}
 const lay=b.layout;const itemHTML=(i,ix)=>{const rot=lay==='collage'?`transform:rotate(${(ix*37%9)-4}deg);`:'';const span=lay==='collage'&&ix%5===0?'grid-column:span 2;':'';
  if(i.type==='img')return`<button onclick="vbItem('${i.id}')" style="${span}${rot}display:block;width:100%;${lay==='masonry'?'margin-bottom:8px;':''}border-radius:10px;overflow:hidden;box-shadow:0 4px 14px rgba(0,0,0,.25);background:#fff;padding:${lay==='collage'?'5px 5px 16px':'0'}"><img src="${i.src}" style="width:100%;display:block;${lay==='grid'?'aspect-ratio:1;object-fit:cover':''}">${i.text?`<div class="tiny" style="color:#333;padding:4px">${esc(i.text)}</div>`:''}</button>`;
  return`<button onclick="vbItem('${i.id}')" style="${span}${rot}display:block;width:100%;${lay==='masonry'?'margin-bottom:8px;':''}${lay==='grid'?'aspect-ratio:1;':''}border-radius:10px;padding:12px;background:${i.color||'#fff'};color:#2a2340;box-shadow:0 4px 14px rgba(0,0,0,.2);font-family:${i.type==='quote'?"'Playfair Display',serif;font-style:italic":"'Patrick Hand',cursive"};font-size:${i.type==='quote'?'.95em':'1.05em'};text-align:center;line-height:1.35">${i.type==='goal'?'🎯 ':'“'}${esc(i.text)}${i.type==='quote'?'”':''}</button>`};
 const cont=lay==='masonry'?`<div style="columns:2;column-gap:8px">${b.items.map(itemHTML).join('')}</div>`:`<div style="display:grid;grid-template-columns:repeat(${lay==='grid'?3:2},1fr);gap:${lay==='collage'?'14px':'8px'}">${b.items.map(itemHTML).join('')}</div>`;
 setMain(`<div class="row"><button class="chip" onclick="vbId=null;render()">← All boards</button><b style="flex:1;text-align:center">${esc(b.name)}</b><button class="chip" onclick="renameBoard()">✏️</button><button class="chip" onclick="delBoard()">🗑️</button></div>
 <div class="row" style="margin-top:10px">${[['grid','▦ Grid'],['collage','🧩 Collage'],['masonry','🧱 Masonry']].map(l=>`<button class="chip ${lay===l[0]?'on':''}" onclick="curBoard().layout='${l[0]}';save();render()">${l[1]}</button>`).join('')}</div>
 <div class="row" style="margin-top:8px">${VB_BG.map((g,i)=>`<button class="swatch ${b.bg===g?'on':''}" style="background:${g}" onclick="curBoard().bg=VB_BG[${i}];save();render()"></button>`).join('')}</div>
 <div style="background:${b.bg};border-radius:18px;padding:${lay==='collage'?18:12}px;margin-top:12px;min-height:220px">${b.items.length?cont:'<p class="center" style="color:#555;padding-top:70px">Your board is empty. Add images, quotes or goals below. ✨</p>'}</div>
 <div class="grid3" style="margin-top:12px"><button class="qa" onclick="vbAddImg()"><b>🖼️</b>Image</button><button class="qa" onclick="vbAddText('quote')"><b>💬</b>Quote</button><button class="qa" onclick="vbAddText('goal')"><b>🎯</b>Goal</button></div>
 <button class="btn block" style="margin-top:12px" onclick="b2save()">💾 Save vision board</button>`)}
const curBoard=()=>(S.boards||[]).find(x=>x.id===vbId);
function b2save(){const b=curBoard();b.saved=new Date().toISOString();save();chime();toast('💾 Vision board saved!')}
function addBoard(){const n=$('#vbN').value.trim()||'My Vision Board';S.boards=S.boards||[];const b={id:uid(),name:n,layout:'collage',bg:VB_BG[0],items:[],created:new Date().toISOString()};S.boards.push(b);vbId=b.id;logAct('🖼️',`Created vision board “${n}”`);save();checkBadges();render()}
function renameBoard(){const b=curBoard();modal(`<h2>✏️ Rename board</h2><input class="f" id="rbN" value="${esc(b.name)}"><button class="btn block" style="margin-top:12px" id="rbS">Save</button>`);$('#rbS').onclick=()=>{b.name=$('#rbN').value.trim()||b.name;save();closeModal();render()}}
function delBoard(){confirmBox('Delete this vision board?',()=>{S.boards=S.boards.filter(x=>x.id!==vbId);vbId=null;save();render()},{danger:true,ok:'Delete'})}
function vbAddImg(){filePick(async f=>{curBoard().items.push({id:uid(),type:'img',src:await readImage(f,800,.72),text:''});save();checkBadges();render()})}
const NOTE_C=['#fff','#fef3c7','#fce7f3','#dbeafe','#dcfce7','#ede9fe'];
function vbAddText(type,item){const b=curBoard();modal(`<h2>${type==='quote'?'💬 Motivational quote':type==='goal'?'🎯 Personal goal':'🖼️ Image caption'}<span class="sp"></span><button class="iconbtn" onclick="closeModal()">✕</button></h2><textarea class="f" id="vbT" style="min-height:80px" placeholder="${type==='quote'?'Write a quote that motivates you':'Write a goal'}">${esc(item?item.text:'')}</textarea>
 ${type==='quote'?`<button class="chip" style="margin-top:8px" onclick="$('#vbT').value=pick(QUOTES)">🎲 Random quote</button>`:''}${type==='goal'&&dreams().length?`<label class="l">Or pick one of your dreams</label><select class="f" onchange="if(this.value)$('#vbT').value=this.value"><option value="">Choose a dream</option>${dreams().map(d=>`<option>${esc(d.title)}</option>`).join('')}</select>`:''}
 ${type!=='img'?`<label class="l">Card color</label><div class="row">${NOTE_C.map((c,i)=>`<button class="swatch ${(item?item.color:NOTE_C[type==='quote'?0:1])===c?'on':''}" data-nc="${c}" style="background:${c}" onclick="document.querySelectorAll('[data-nc]').forEach(x=>x.classList.remove('on'));this.classList.add('on')"></button>`).join('')}</div>`:''}
 <button class="btn block" style="margin-top:12px" id="vbS">${item?'Save':'Add to board'}</button>`);
 $('#vbS').onclick=()=>{const t=$('#vbT').value.trim();if(!t&&type!=='img')return toast('Write something first.');const col=document.querySelector('[data-nc].on');if(item){item.text=t;if(col)item.color=col.dataset.nc}else b.items.push({id:uid(),type,text:t,color:col?col.dataset.nc:'#fff'});save();checkBadges();closeModal();render()}}
function vbItem(id){const b=curBoard(),i=b.items.find(x=>x.id===id),ix=b.items.indexOf(i);modal(`<h2>Edit item<span class="sp"></span><button class="iconbtn" onclick="closeModal()">✕</button></h2>${i.type==='img'?`<img src="${i.src}" style="width:100%;border-radius:12px;max-height:240px;object-fit:contain">`:`<div class="step">${esc(i.text)}</div>`}
 <div class="row" style="margin-top:12px"><button class="btn ghost sm" onclick="closeModal();vbAddText('${i.type}',curBoard().items[${ix}])">✏️ ${i.type==='img'?'Caption':'Edit'}</button><button class="btn ghost sm" ${ix===0?'disabled':''} onclick="vbMove(${ix},-1)">⬅️ Move</button><button class="btn ghost sm" ${ix===b.items.length-1?'disabled':''} onclick="vbMove(${ix},1)">Move ➡️</button><button class="btn danger sm" onclick="curBoard().items.splice(${ix},1);save();closeModal();render()">🗑️ Delete</button></div>`)}
function vbMove(ix,dir){const a=curBoard().items;[a[ix],a[ix+dir]]=[a[ix+dir],a[ix]];save();closeModal();render()}

/* ---------- Memory collection ---------- */
let memTab='gallery',memPreset=null,memDraft2=null;
function render_memories(){const M=S.memories||[];const tabs=`<div class="tabs">${[['gallery','🖼️ Gallery'],['scrap','📒 Scrapbook'],['add','➕ Add memory']].map(t=>`<button class="${memTab===t[0]?'on':''}" onclick="memTab='${t[0]}';render()">${t[1]}</button>`).join('')}</div>`;
 if(memTab==='add'){const p=memDraft2||(memDraft2={media:[],img:null,before:null,cap:'',story:'',date:dkey(),location:'',dreamId:'',...(memPreset||{})});memPreset=null;
  return setMain(tabs+`<div class="card"><h3>📸 Save an experience</h3>${mediaPickerHTML(p)}<div class="tiny muted" style="margin:14px 0 6px">Optional: Before & after photos</div><div class="grid2">${[['before','Before'],['img','After / actual']].map(([k,l])=>`<div><div class="tiny muted" style="margin-bottom:4px">${l} photo</div>${p[k]?`<div style="position:relative"><img src="${p[k]}" style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:12px"><button onclick="memSync();memDraft2.${k}=null;render()" style="position:absolute;top:6px;right:6px;width:26px;height:26px;border-radius:50%;background:#000b;color:#fff">✕</button></div>`:`<button class="iconbtn" style="width:100%;height:auto;aspect-ratio:1;border-radius:12px;font-size:1.6em" onclick="memSync();memPic('${k}')">📷</button>`}</div>`).join('')}</div>
  <label class="l">Title / caption</label><input class="f" id="mC" value="${esc(p.cap)}" placeholder="e.g. Finally saw the whale sharks!">
  <label class="l">Experience story</label><textarea class="f" id="mS" placeholder="What happened? How did it feel?">${esc(p.story)}</textarea>
  <div class="grid2"><div><label class="l">Date accomplished</label><input class="f" type="date" id="mD" value="${p.date}" max="${dkey()}"></div><div><label class="l">Location</label><input class="f" id="mL" value="${esc(p.location)}" placeholder="Where?"></div></div>
  <label class="l">Linked dream</label><select class="f" id="mDr"><option value="">None</option>${dreams().map(d=>`<option value="${d.id}" ${p.dreamId===d.id?'selected':''}>${catOf(d.cat)[1]} ${esc(d.title.slice(0,40))}</option>`).join('')}</select>
  <button class="btn block" style="margin-top:12px" onclick="addMem2()">💾 Save to memory collection</button></div>`)}
 if(!M.length)return setMain(tabs+`<div class="card center"><div style="font-size:3em">📸</div><p class="muted">No memories yet. Save photos and stories from the dreams you've lived.</p><button class="btn" onclick="memTab='add';render()">➕ Add a memory</button></div>`);
 const sorted=[...M].sort((a,b)=>(b.date||'').localeCompare(a.date||''));
 const dl=`<div class="row" style="margin-bottom:8px"><button class="btn ghost sm" onclick="downloadMemories()">⬇️ Download collection</button><span class="tiny muted">${M.length} memories</span></div>`;
 if(memTab==='scrap')return setMain(tabs+dl+`<div style="background:#f5ecd9;border-radius:18px;padding:18px 14px;color:#3b2f1e;background-image:radial-gradient(#e5d6b8 1px,transparent 1px);background-size:16px 16px"><h2 style="font-family:'Patrick Hand',cursive;text-align:center;margin:0 0 12px;font-size:1.6em;color:#3b2f1e">📒 ${esc(S.user.name.split(' ')[0])}'s Scrapbook</h2>
  ${sorted.map((m,i)=>`<div onclick="viewMem('${m.id}')" style="cursor:pointer;background:#fff;padding:10px 10px 14px;margin:0 auto 22px;width:${m.img||m.before?'86%':'92%'};transform:rotate(${i%2?2.2:-2}deg);box-shadow:0 6px 16px rgba(0,0,0,.18);position:relative"><span style="position:absolute;top:-10px;left:40%;width:70px;height:20px;background:${pick(['#fbcfe8aa','#bae6fdaa','#fde68aaa','#bbf7d0aa'])};transform:rotate(-4deg)"></span>
  ${m.before&&m.img?`<div class="grid2" style="gap:6px"><div><img src="${m.before}" style="width:100%;aspect-ratio:1;object-fit:cover"><div class="tiny center" style="color:#888">Before</div></div><div><img src="${m.img}" style="width:100%;aspect-ratio:1;object-fit:cover"><div class="tiny center" style="color:#888">After</div></div></div>`:(m.img||m.before)?`<img src="${m.img||m.before}" style="width:100%;max-height:260px;object-fit:cover">`:''}
  <div style="font-family:'Patrick Hand',cursive;font-size:1.25em;margin-top:6px">${esc(m.cap||'A memory')}</div>${m.story?`<div style="font-family:'Patrick Hand',cursive;font-size:1em;color:#5b4a33;line-height:1.35">${esc(m.story.slice(0,160))}${m.story.length>160?'…':''}</div>`:''}<div style="font-size:.72em;color:#8a7558;margin-top:4px">📅 ${fmtDate((m.date||dkey())+'T12:00')}${m.location?' · 📍 '+esc(m.location):''}${m.savedAt?' · 🕒 '+fmtTime(m.savedAt):''}</div></div>`).join('')}</div>`);
 setMain(tabs+dl+`<div class="grid3">${sorted.map(m=>`<button onclick="viewMem('${m.id}')" style="aspect-ratio:1;border-radius:12px;overflow:hidden;background:var(--card2);position:relative">${m.img||m.before?`<img src="${m.img||m.before}" style="width:100%;height:100%;object-fit:cover">`:`<div style="display:grid;place-items:center;height:100%;font-size:2em">📝</div>`}${m.before&&m.img?'<span class="tiny" style="position:absolute;top:4px;left:4px;background:#000a;color:#fff;border-radius:6px;padding:1px 5px">B/A</span>':''}${(m.media||[])[0]&&m.media[0].type==='video'&&m.imgFromMedia?'<span class="mplay">▶</span>':''}${(m.media||[]).length?`<span class="tiny" style="position:absolute;top:4px;right:4px;background:#000a;color:#fff;border-radius:6px;padding:1px 6px">${m.media.some(x=>x.type==='video')?'▶ ':''}${m.media.length}</span>`:''}<span class="tiny" style="position:absolute;left:0;right:0;bottom:0;background:linear-gradient(transparent,rgba(0,0,0,.75));color:#fff;padding:4px">${esc((m.cap||'').slice(0,20))}</span></button>`).join('')}</div>`)}
function memSync(){const g=id=>{const e=document.getElementById(id);return e?e.value:null};const p=memDraft2;if(!p)return;const v={cap:g('mC'),story:g('mS'),date:g('mD'),location:g('mL'),dreamId:g('mDr')};for(const k in v)if(v[k]!==null)p[k]=v[k]}
