function addMem2(){memSync();const p=memDraft2;if(!p.cap.trim()&&!p.img&&!p.before&&!(p.media&&p.media.length))return toast('Add a photo, video or a caption.');S.memories=S.memories||[];const m={id:uid(),imgFromMedia:!p.img&&!!(p.media||[]).find(x=>x.thumb),media:(p.media||[]).map(x=>({id:x.id,type:x.type,name:x.name,thumb:x.thumb,dur:x.dur,url:x.url||(typeof uploadedURL!=='undefined'&&uploadedURL[x.id])||null})),img:p.img||((p.media||[]).find(x=>x.thumb)||{}).thumb||null,before:p.before,cap:p.cap.trim(),story:p.story.trim(),date:p.date||dkey(),location:p.location.trim(),dreamId:p.dreamId,savedAt:new Date().toISOString()};S.memories.push(m);memDraft2=null;logAct('📸',`Saved memory “${m.cap||'Untitled'}”`);S.activity[0].mid=m.id;if(S.notifs&&S.notifs[0]&&S.notifs[0].act&&S.notifs[0].ts===S.activity[0].ts)S.notifs[0].mid=m.id;save();checkBadges();toast(`📸 Memory saved at ${fmtTime(new Date())}!`);memTab='gallery';render()}
