/* ---------- Analytics ---------- */
let anYear=new Date().getFullYear();
function render_analytics(){const D=dreams(),st=dStat();if(!D.length)return setMain(`<div class="card center"><div style="font-size:3em">📊</div><p class="muted">Add some dreams to see your analytics.</p><button class="btn" onclick="go('dreams')">Go to bucket list</button></div>`);
 const cc={};D.forEach(d=>cc[d.cat]=(cc[d.cat]||0)+1);const cats=Object.entries(cc).sort((a,b)=>b[1]-a[1]);const top=catOf(cats[0][0]);
 const ms=monthsBack(12);const comp=ms.map(m=>D.filter(d=>d.completedAt&&monthKey(d.completedAt)===monthKey(m)).length),add=ms.map(m=>D.filter(d=>monthKey(d.created)===monthKey(m)).length);const mx=Math.max(1,...comp,...add);
 const done=D.filter(d=>d.status==='done');const rate=Math.round(done.length/D.length*100);const avgDays=done.length?Math.round(done.reduce((s,d)=>s+Math.max(0,daysBetween(d.created,d.completedAt)),0)/done.length):0;const withT=done.filter(d=>d.target);const onTime=withT.length?Math.round(withT.filter(d=>dkey(d.completedAt)<=d.target).length/withT.length*100):null;
 const overdue=D.filter(d=>d.status!=='done'&&d.target&&daysLeft(d.target)<0).length;
 const yd=D.filter(d=>new Date(d.created).getFullYear()===anYear),yc=done.filter(d=>new Date(d.completedAt).getFullYear()===anYear);const ycc={};yc.forEach(d=>ycc[d.cat]=(ycc[d.cat]||0)+1);const ytop=Object.entries(ycc).sort((a,b)=>b[1]-a[1])[0];
 const years=[...new Set([...D.map(d=>new Date(d.created).getFullYear()),new Date().getFullYear()])].sort();
 const R=2*Math.PI*42;
 setMain(`<div class="grid4">${[['🪣',st.total,'Total'],['✅',st.done,'Completed'],['🚀',st.ongoing,'Ongoing'],['⏸️',st.pending,'Pending']].map(s=>`<div class="stat"><div class="big" style="font-size:1.3em">${s[0]} ${s[1]}</div><div class="lbl">${s[2]}</div></div>`).join('')}</div>
 <div class="card" style="display:flex;gap:16px;align-items:center"><svg width="110" height="110" viewBox="0 0 110 110"><circle cx="55" cy="55" r="42" fill="none" stroke="currentColor" opacity=".1" stroke-width="12"/><circle cx="55" cy="55" r="42" fill="none" stroke="#22c55e" stroke-width="12" stroke-linecap="round" stroke-dasharray="${R}" stroke-dashoffset="${R*(1-rate/100)}" transform="rotate(-90 55 55)"/><text x="55" y="61" text-anchor="middle" font-size="20" font-weight="700" fill="currentColor">${rate}%</text></svg>
  <div style="flex:1"><h3 style="margin-bottom:6px">🏁 Completion statistics</h3><div class="small">Completion rate: <b>${rate}%</b></div><div class="small">Avg. time to complete: <b>${done.length?avgDays+' days':'N/A'}</b></div><div class="small">Finished on time: <b>${onTime===null?'N/A':onTime+'%'}</b></div><div class="small">Overdue now: <b style="color:${overdue?'var(--bad)':'inherit'}">${overdue}</b></div></div></div>
 <div class="card"><h3>🏷️ Most used category<span class="sp"></span><span class="chip">${top[1]} ${esc(top[2])}</span></h3>${cats.map(([k,n])=>{const c=catOf(k);const dn=D.filter(d=>d.cat===k&&d.status==='done').length;return`<div class="row" style="flex-wrap:nowrap;margin:6px 0"><span style="width:26px">${c[1]}</span><span class="small" style="width:120px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(c[2])}</span><div class="bar" style="flex:1;height:10px"><i style="width:${n/cats[0][1]*100}%;background:${c[3]}"></i></div><span class="tiny" style="width:44px;text-align:right">${dn}/${n}</span></div>`}).join('')}</div>
 <div class="card"><h3>📅 Monthly progress (12 months)</h3><div style="display:flex;gap:4px;align-items:flex-end;height:120px">${ms.map((m,i)=>`<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%"><div style="display:flex;gap:1px;align-items:flex-end;width:100%;justify-content:center"><div style="width:45%;height:${add[i]/mx*90+2}px;background:var(--accent);opacity:.55;border-radius:3px"></div><div style="width:45%;height:${comp[i]/mx*90+2}px;background:#22c55e;border-radius:3px"></div></div><div class="tiny muted" style="font-size:.6em">${m.toLocaleDateString(undefined,{month:'narrow'})}</div></div>`).join('')}</div><div class="tiny muted center" style="margin-top:6px"><span style="color:var(--accent)">■</span> Added &nbsp; <span style="color:#22c55e">■</span> Completed</div></div>
 <div class="card"><h3>🗓️ Yearly dream summary<span class="sp"></span><select class="chip" onchange="anYear=+this.value;render()">${years.map(y=>`<option ${y===anYear?'selected':''}>${y}</option>`).join('')}</select></h3>
  <div class="grid3"><div class="stat"><div class="big" style="font-size:1.3em">${yd.length}</div><div class="lbl">Dreams added</div></div><div class="stat"><div class="big" style="font-size:1.3em">${yc.length}</div><div class="lbl">Completed</div></div><div class="stat"><div class="big" style="font-size:1.3em">${ytop?catOf(ytop[0])[1]:'N/A'}</div><div class="lbl">Top category</div></div></div>
  <p class="small" style="line-height:1.6">${yc.length?`In ${anYear}, you made <b>${yc.length}</b> dream${yc.length===1?'':'s'} come true${ytop?`, mostly in <b>${esc(catOf(ytop[0])[2])}</b>`:''}. ${yc.length>=5?'What an amazing year! 🌟':'Every dream counts! 💜'}`:`No dreams completed in ${anYear} yet. ${anYear===new Date().getFullYear()?'There\'s still time! ✨':''}`}</p>
  ${yc.length?`<div class="list">${yc.sort((a,b)=>a.completedAt.localeCompare(b.completedAt)).map(d=>`<button class="item" style="width:100%;text-align:left" onclick="openDream('${d.id}')"><span>🏁</span><span class="small" style="flex:1">${esc(d.title)}</span><span class="tiny muted">${fmtDate(d.completedAt)}</span></button>`).join('')}</div>`:''}</div>`)}

/* ---------- Monthly challenges ---------- */
const CHALLENGES=[
 {e:'🏁',t:'Complete 1 dream this month',f:mk=>[dreams().filter(d=>d.completedAt&&monthKey(d.completedAt)===mk).length,1]},
 {e:'🪣',t:'Add 3 new dreams',f:mk=>[dreams().filter(d=>monthKey(d.created)===mk).length,3]},
 {e:'📓',t:'Write 3 journal entries linked to dreams',f:mk=>[posted().filter(e=>e.dreamId&&monthKey(e.date)===mk).length,3]},
 {e:'📈',t:'Update progress on 5 dreams',f:mk=>[(S.progressLog||[]).filter(p=>monthKey(p.ts)===mk&&p.to>p.from).length,5]},
 {e:'📸',t:'Save 2 memories',f:mk=>[(S.memories||[]).filter(m=>(m.date||'').startsWith(mk)).length,2]},
 {e:'🖼️',t:'Add 4 items to a vision board',f:mk=>[(S.boards||[]).reduce((s,b)=>s+b.items.length,0)>=4?4:(S.boards||[]).reduce((s,b)=>s+b.items.length,0),4]},
 {e:'💌',t:'Write a letter to your future self',f:mk=>[S.letters.filter(l=>monthKey(l.created)===mk).length,1]}];
function monthChallenges(){const m=new Date().getMonth()+new Date().getFullYear()*12;return[0,1,2].map(i=>CHALLENGES[(m*3+i*4)%CHALLENGES.length]).filter((c,i,a)=>a.indexOf(c)===i)}
function render_challenges(){const mk=monthKey();const L=monthChallenges();const done=L.filter(c=>{const[a,b]=c.f(mk);return a>=b}).length;const endD=new Date(new Date().getFullYear(),new Date().getMonth()+1,0);
 setMain(`<div class="card center" style="background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 50%,transparent),var(--card))"><div style="font-size:3em">🏆</div><h2 style="margin:4px 0">${new Date().toLocaleDateString(undefined,{month:'long',year:'numeric'})} challenges</h2><div class="small">${done}/${L.length} completed · ${daysBetween(new Date(),endD)} days left</div></div>
 ${L.map(c=>{const[a,b]=c.f(mk);const ok=a>=b;return`<div class="card" style="${ok?'border-color:#22c55e':''}"><div class="row" style="flex-wrap:nowrap"><span style="font-size:2em">${ok?'✅':c.e}</span><div style="flex:1"><b>${c.t}</b><div class="bar" style="margin-top:8px"><i style="width:${Math.min(100,a/b*100)}%;background:${ok?'#22c55e':'var(--accent)'}"></i></div><div class="tiny muted" style="margin-top:4px">${Math.min(a,b)} / ${b}</div></div></div></div>`}).join('')}
 <div class="card"><h3>💡 Daily dream suggestion</h3>${(()=>{const i=dailyIdea();return`<div class="step"><span>${catOf(i[1])[1]}</span><b style="flex:1">${esc(i[0])}</b><button class="btn sm" onclick="addIdea(${IDEAS.indexOf(i)})">➕</button></div>`})()}</div>`)}

/* ---------- Notifications ---------- */
function addNotif(k,ic,t,showToast){S.notifs=S.notifs||[];if(S.notifs.some(n=>n.k===k))return false;S.notifs.unshift({k,ic,t,ts:new Date().toISOString(),read:false});S.notifs=S.notifs.slice(0,80);if(showToast)toast(`${ic} ${esc(t)}`,5000);return true}
function genNotifs(silent){const N=S.settings.notif;const today=dkey();let fresh=0;
 dreams().filter(d=>d.status!=='done'&&d.target).forEach(d=>{const n=daysLeft(d.target);
  if(N.target!==false&&n>=0&&n<=7&&addNotif('tg-'+d.id+'-'+today,'⏰',n===0?`“${d.title}” is due today!`:`“${d.title}” is due in ${n} day${n===1?'':'s'}.`))fresh++;
  if(N.target!==false&&n<0&&addNotif('od-'+d.id+'-'+today,'⚠️',`“${d.title}” is ${-n} day${n===-1?'':'s'} overdue. Update the date or keep going!`))fresh++;
  if(N.upcoming!==false&&n>7&&n<=30&&addNotif('up-'+d.id+'-'+monthKey(),'📅',`Coming up: “${d.title}” in ${n} days.`))fresh++});
 if(N.challenge!==false&&addNotif('ch-'+monthKey(),'🏆',`New ${new Date().toLocaleDateString(undefined,{month:'long'})} challenges are here!`))fresh++;
 if(N.progress!==false)dreams().filter(d=>['plan','prog'].includes(d.status)&&daysBetween(d.updated,new Date())>=14).forEach(d=>{if(addNotif('pr-'+d.id+'-'+monthKey(),'📈',`How's “${d.title}” going? Update your progress.`))fresh++});
 save();updateBell();if(fresh&&!silent)toast(`🔔 You have ${fresh} new notification${fresh===1?'':'s'}.`)}
function updateBell(){const b=$('#bell');if(!b)return;const n=(S.notifs||[]).filter(x=>!x.read).length;b.innerHTML='🔔'+(n?`<span style="position:absolute;top:-3px;right:-3px;min-width:18px;height:18px;border-radius:9px;background:var(--bad);color:#fff;font-size:.62em;display:grid;place-items:center;padding:0 4px">${n>9?'9+':n}</span>`:'');b.style.position='relative'}
function render_notifs(){const N=S.notifs||[];const st=S.settings.notif;setMain(`<div class="row"><button class="chip" onclick="(S.notifs||[]).forEach(n=>n.read=true);save();render()">✓ Mark all read</button><button class="chip" onclick="S.notifs=[];save();render()">🗑️ Clear</button><button class="chip" onclick="genNotifs();render()">🔄 Check now</button></div>
 <div class="card">${N.length?`<div class="list">${N.map(n=>{const P=n.act?actPic(n):{};const op=P.open||n.open||'';return`<div class="item nitem${op?' tap':''}" style="${n.read?'opacity:.6':''}"${op?` role="button" tabindex="0" onclick="${op}"`:''}>${P.url?`<img src="${esc(P.url)}" alt="" class="nthumb">`:`<span style="font-size:1.4em">${n.ic}</span>`}<div style="flex:1;min-width:0" class="small">${esc(n.t)}<div class="tiny muted">${n.act?actWhen(n.ts):timeAgo(n.ts)}</div></div>${n.read?'':'<span style="width:8px;height:8px;border-radius:50%;background:var(--accent);flex-shrink:0"></span>'}${op?'<span class="muted" style="flex-shrink:0">›</span>':''}</div>`}).join('')}</div>`:'<p class="muted small center">No notifications yet. 🔕</p>'}</div>
 <div class="card"><h3>⚙️ Notification settings</h3>${[['target','⏰ Target date reminders'],['upcoming','📅 Upcoming dream reminders'],['challenge','🏆 Monthly challenge notifications'],['progress','📈 Progress reminders'],['achieve','🏅 Achievement notifications']].map(r=>`<div class="setrow"><div class="t small">${r[1]}</div><button class="switch ${st[r[0]]!==false?'on':''}" onclick="S.settings.notif.${r[0]}=!(S.settings.notif.${r[0]}!==false);save();render()"></button></div>`).join('')}</div>`);N.forEach(n=>n.read=true);save();setTimeout(updateBell,50)}

