const SCENE_CSS=`
#bg svg,.pv svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.la{transform-box:fill-box;transform-origin:center;animation-iteration-count:infinite;animation-timing-function:ease-in-out}
.tw{animation-name:sc_tw;animation-duration:3s}@keyframes sc_tw{50%{opacity:.15}}
.flu{animation-name:sc_flu;animation-duration:9s}@keyframes sc_flu{50%{transform:translateY(-16px)}}
.bob{animation-name:sc_bob;animation-duration:2.2s}@keyframes sc_bob{50%{transform:translateY(-10px)}}
.rise{animation-name:sc_rise;animation-duration:14s;animation-timing-function:linear}@keyframes sc_rise{0%{transform:translate(0,0);opacity:0}10%{opacity:1}50%{transform:translate(18px,-420px)}90%{opacity:.9}100%{transform:translate(-10px,-880px);opacity:0}}
.fall{animation-name:sc_fall;animation-duration:12s;animation-timing-function:linear}@keyframes sc_fall{0%{transform:translate(0,0) rotate(0)}50%{transform:translate(-50px,420px) rotate(260deg)}100%{transform:translate(-120px,860px) rotate(540deg)}}
.drift{animation-name:sc_drift;animation-duration:70s;animation-timing-function:linear}@keyframes sc_drift{from{transform:translateX(-60px)}to{transform:translateX(620px)}}
.beam{transform-origin:50% 0;animation-name:sc_beam;animation-duration:6s}@keyframes sc_beam{0%,100%{transform:rotate(-9deg)}50%{transform:rotate(9deg)}}
.pulse{animation-name:sc_pulse;animation-duration:5s}@keyframes sc_pulse{50%{transform:scale(1.08);opacity:.75}}
.breathe{animation-name:sc_breathe;animation-duration:12s}@keyframes sc_breathe{50%{transform:scale(1.07) translate(-6px,6px)}}
.slide{animation-name:sc_slide;animation-duration:9s}@keyframes sc_slide{50%{transform:translateX(240px)}}
.treesway{transform-origin:50% 100%;animation-name:sc_tree;animation-duration:5s}@keyframes sc_tree{50%{transform:rotate(3deg)}}
.codefall{transform-box:view-box;animation-name:sc_code;animation-duration:26s;animation-timing-function:linear}@keyframes sc_code{from{transform:translateY(0)}to{transform:translateY(-800px)}}
.type{transform-origin:0 50%;animation-name:sc_type;animation-duration:4s}@keyframes sc_type{0%{transform:scaleX(0)}45%,85%{transform:scaleX(1)}100%{transform:scaleX(0)}}
.blink{animation-name:sc_blink;animation-duration:1s;animation-timing-function:steps(1)}@keyframes sc_blink{50%{opacity:0}}
.spinslow{animation-name:sc_spin;animation-duration:40s;animation-timing-function:linear}@keyframes sc_spin{to{transform:rotate(360deg)}}
.bounce{animation-name:sc_bounce;animation-duration:1.3s;animation-timing-function:cubic-bezier(.45,0,.55,1)}@keyframes sc_bounce{0%,100%{transform:translateY(0) scale(1.06,.92)}12%{transform:translateY(-8px) scale(1,1)}50%{transform:translateY(-150px)}88%{transform:translateY(-8px) scale(1,1)}}
.ballspin{animation-name:sc_spin;animation-duration:2.6s;animation-timing-function:linear}
.shadow{animation-name:sc_shadow;animation-duration:1.3s}@keyframes sc_shadow{50%{transform:scale(.55);opacity:.3}}
.dust{animation-name:sc_dust;animation-duration:12s}@keyframes sc_dust{0%{transform:translate(0,0);opacity:0}20%{opacity:.8}50%{transform:translate(30px,-60px)}80%{opacity:.6}100%{transform:translate(-10px,-120px);opacity:0}}
.flipbook{animation-name:sc_bob;animation-duration:4s}
.dash{animation-name:sc_dash;animation-duration:2s;animation-timing-function:linear}@keyframes sc_dash{to{stroke-dashoffset:-56}}
.glint{animation-name:sc_tw;animation-duration:2.4s}
.pinb{animation-name:sc_pin;animation-duration:1.6s}@keyframes sc_pin{50%{transform:scale(1.5)}}
.wob{animation-name:sc_wob;animation-duration:5s}@keyframes sc_wob{0%,100%{transform:rotate(-24deg)}50%{transform:rotate(26deg)}}
.eq{transform-origin:center;animation-name:sc_eq;animation-duration:1.2s}@keyframes sc_eq{50%{transform:scaleY(.25)}}
.pv .la{animation-play-state:running}
@media (prefers-reduced-motion:reduce){.la{animation:none!important}}`;

