function styleCardsHTML(){const st=S.settings;const isOrig=st.style==='galaxy'&&!st.customBg&&!st.bgColor;return`<div class="card"><h3>🎨 Choose your style<span class="sp"></span>${isOrig?'<span class="tiny muted">Original style</span>':`<button class="chip" style="border-color:var(--bad);color:var(--bad)" onclick="removeStyle()">✕ Remove style</button>`}</h3><div class="stylegrid">${Object.entries(THEMES).map(([k,t])=>{const on=st.style===k&&!st.customBg&&!st.bgColor;const AL={books:'xMidYMax',nature:'xMidYMax',cute:'xMidYMax',kdrama:'xMidYMax',programmer:'xMidYMax',minimal:'xMidYMin',gaming:'xMidYMin'};const pv=k==='galaxy'?t.bg:'transparent';const live=k==='galaxy'?'':SCENE_FN[k]('pv'+k+'_').replace('xMidYMid slice',(AL[k]||'xMidYMid')+' slice');return`<button class="stylecard ${on?'on':''}" onclick="setStyle('${k}')"><div class="pv" style="background:${pv}">${live}${k==='galaxy'?'<span style="position:absolute;inset:0;background:radial-gradient(circle at 30% 30%,#fff 1px,transparent 1.5px) 0 0/18px 18px;opacity:.6"></span>':''}${on?(k==='galaxy'?'<span class="ck">✓</span>':`<span class="ck" style="background:#ef4444" title="Remove style" onclick="event.stopPropagation();removeStyle()">✕</span>`):''}</div><div class="nm">${t.em} ${esc(t.n)}</div><div class="sw">${t.pal.map(c=>`<i style="background:${c}"></i>`).join('')}</div></button>`}).join('')}</div></div>`}
