const clk={end:0,left:0,total:0,run:false,label:''};
function clockText(){const now=new Date();let t='🕐 '+now.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});if(clk.run||clk.left>0){const l=clk.run?Math.max(0,Math.ceil((clk.end-Date.now())/1000)):clk.left;t+=` · ${clk.run?'⏳':'⏸️'}${fmtDur(l)}`}return t}
