let usTab='usage';
showUsage=function(){modal(`<h2>🕐 ${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}<span class="sp"></span><button class="iconbtn" onclick="closeModal()">✕</button></h2><div class="center" style="font-size:2.4em;font-weight:700;margin:0 0 10px;font-variant-numeric:tabular-nums" id="bigClock">${new Date().toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit',second:'2-digit'})}</div><div id="tmBox"></div>`);drawTimer()};
function drawTimer(){const b=$('#tmBox');if(!b)return;if(usTab==='usage'){b.innerHTML=`<div class="grid3"><div class="stat"><div class="big" style="font-size:1.3em" id="ussess">${fmtDur(sessionSec)}</div><div class="lbl">This session</div></div><div class="stat"><div class="big" style="font-size:1.3em" id="usday">${fmtDur(S.usage.sec)}</div><div class="lbl">Today</div></div><div class="stat"><div class="big" style="font-size:1.3em" id="ustot">${fmtDur(S.usage.total||0)}</div><div class="lbl">All time</div></div></div><p class="small muted">${S.settings.rest?'You get a reminder at 30 minutes and an alarm at 1 hour.':'Rest reminders are off.'}</p><button class="btn block" onclick="closeModal();startRest()">🌿 Rest mode now</button>${clockToggleBtn()}`;return}
 const l=clk.run?Math.max(0,Math.ceil((clk.end-Date.now())/1000)):clk.left;const active=clk.run||clk.left>0;
 b.innerHTML=`<div class="center"><div class="ring" style="margin:6px auto 10px;width:150px;height:150px"><svg width="150" height="150" viewBox="0 0 120 120"><circle cx="60" cy="60" r="52" stroke="currentColor" opacity=".12" stroke-width="9" fill="none"/><circle id="tmRing" cx="60" cy="60" r="52" stroke="var(--accent)" stroke-width="9" fill="none" stroke-linecap="round" stroke-dasharray="326.7" stroke-dashoffset="${active&&clk.total?326.7*(1-(clk.total-l)/clk.total):326.7}" transform="rotate(-90 60 60)" style="transition:stroke-dashoffset 1s linear"/></svg><div class="lab" style="flex-direction:column;display:flex;align-items:center;justify-content:center"><span id="tmLeft" style="font-size:1.6em">${fmtDur(active?l:(+($('#tmMin')?.value)||5)*60)}</span>${active?'<span class="tiny muted" style="font-weight:400">left</span>':''}</div></div>${active?`<div class="small" id="tmDone" style="margin-bottom:6px">✅ <b>${fmtDur(clk.total-l)}</b> done of ${fmtDur(clk.total)}</div><div class="bar" style="max-width:240px;margin:0 auto 12px"><i id="tmBar" style="width:${(clk.total-l)/clk.total*100}%;transition:width 1s linear"></i></div>`:''}
 ${active?`${clk.label?`<div class="small muted" style="margin-bottom:8px">${esc(clk.label)}</div>`:''}<div class="row" style="justify-content:center"><button class="btn" onclick="tmPause()">${clk.run?'⏸️ Pause':'▶️ Resume'}</button><button class="btn ghost" onclick="tmAdd(60)">+1 min</button><button class="btn ghost" onclick="tmReset()">↺ Reset</button></div>`
 :`<div class="row" style="justify-content:center">${[1,5,10,15,25,30,60].map(m=>`<button class="chip" onclick="tmStart(${m})">${m<60?m+' min':'1 hr'}</button>`).join('')}</div><div class="row" style="flex-wrap:nowrap;margin-top:12px"><input class="f" id="tmMin" type="number" min="1" max="600" value="5" style="width:90px;text-align:center"><span class="small muted">min</span><input class="f" id="tmLab" placeholder="Label (optional)" maxlength="40"></div><button class="btn block" style="margin-top:10px" onclick="tmStart(+$('#tmMin').value,$('#tmLab').value)">▶️ Start timer</button>`}
 <p class="tiny muted" style="margin-top:10px">The timer keeps running while you use other pages. The time left shows on the top bar.</p></div>${timerHistoryHTML()}${clockToggleBtn()}`}
function clockToggleBtn(){return`<button class="btn ghost block" style="margin-top:10px" onclick="closeModal();setTimerVisible(false)">✕ Hide the clock from the top bar</button>`}
function tmStart(m,label=''){m=Math.max(1,Math.min(600,+m||0));if(!m)return toast('Enter the minutes.');clk.total=m*60;clk.end=Date.now()+clk.total*1000;clk.left=0;clk.run=true;clk.label=String(label||'').trim();beep(660,.1);tickClock();drawTimer()}
function tmPause(){if(clk.run){clk.left=Math.max(0,Math.ceil((clk.end-Date.now())/1000));clk.run=false}else if(clk.left>0){clk.end=Date.now()+clk.left*1000;clk.left=0;clk.run=true}tickClock();drawTimer()}
function tmAdd(s){if(clk.run)clk.end+=s*1000;else clk.left+=s;clk.total+=s;tickClock()}
function tmReset(){if(clk.total){const l=clk.run?Math.max(0,Math.ceil((clk.end-Date.now())/1000)):clk.left;const el=clk.total-l;if(el>=5)logTimer(el,false)}clk.run=false;clk.left=0;clk.total=0;clk.label='';tickClock();drawTimer()}
setTimerVisible=function(v){S.settings.showTimer=v;save();const tm=$('#tmr');if(tm)tm.classList.toggle('hide',!v);if(page==='settings')render();toast(v?'🕐 The clock is back on the top bar.':'🕐 Clock hidden. Turn it back on in Settings → Rest reminders.')};

function fmtMin(sec){const m=Math.floor(sec/60),x=sec%60;return m?`${m} min${m===1?'':'s'}${x?` ${x} sec`:''}`:`${x} sec`}
function logTimer(sec,completed){S.timerLog=S.timerLog||[];S.timerLog.unshift({label:clk.label,planned:clk.total,done:sec,completed,ts:new Date().toISOString()});S.timerLog=S.timerLog.slice(0,50);save()}
function timerHistoryHTML(){const L=(S.timerLog||[]).filter(t=>dkey(t.ts)===dkey());const tot=L.reduce((a,t)=>a+t.done,0);
 return`<div class="card" style="margin:12px 0 0"><h3>📋 Finished today<span class="sp"></span><span class="small">Total: <b>${fmtMin(tot)}</b></span></h3>${L.length?`<div class="list">${L.map(t=>`<div class="item"><span style="font-size:1.3em">${t.completed?'✅':'⏹️'}</span><div style="flex:1" class="small"><b>${fmtMin(t.done)}</b>${t.completed?'':` <span class="muted">of ${fmtMin(t.planned)}</span>`}${t.label?` · ${esc(t.label)}`:''}<div class="tiny muted">${t.completed?'Completed':'Stopped early'} at ${fmtTime(t.ts)}</div></div></div>`).join('')}</div>${L.length?'<button class="chip" style="margin-top:8px" onclick="S.timerLog=(S.timerLog||[]).filter(t=>dkey(t.ts)!==dkey());save();drawTimer()">🗑️ Clear today</button>':''}`:'<p class="tiny muted" style="margin:0">Your finished timers will show here.</p>'}</div>`}

