let boostIdx=null;
function boostToday(){const dow=new Date().getDay(),B=DAY_BOOST[dow];const dayNum=Math.floor((Date.now()-new Date().getTimezoneOffset()*6e4)/864e5);if(boostIdx===null)boostIdx=dayNum%B.m.length;return{B,msg:B.m[boostIdx%B.m.length].replace(/\{n\}/g,S.user.name.split(' ')[0]),tip:B.t[boostIdx%B.t.length]}}
let boostSpeaking=false;
function aiBoost(tabs){const{B,msg,tip,SL}=boostToday();const dateStr=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});
 setMain(tabs+`<div class="card center" style="background:linear-gradient(150deg,${B.c[0]}66,${B.c[1]}55),var(--card);overflow:hidden">
 <div class="tiny" style="opacity:.8;letter-spacing:.5px">${SL.e} ${SL.name.toUpperCase()} MOOD BOOST · ${dateStr.toUpperCase()}</div>
 <div id="bAv" style="width:112px;height:112px;margin:14px auto 6px;border-radius:50%;padding:4px;background:conic-gradient(from 200deg,#60a5fa,#a78bfa,#f472b6,#fbbf24,#60a5fa)"><div style="width:100%;height:100%;border-radius:50%;background:#1b1340;display:grid;place-items:center">${HEAD_LOGO().replace('class="hl"','class="hl" style="width:78px;height:78px"')}</div></div>
 <div class="small" id="bSt" style="opacity:.85;min-height:1.3em">${SL.e} ${B.d} ${SL.name.toLowerCase()} message from Lumi</div>
 <p id="bMsg" style="font-size:1.08em;line-height:1.6;font-weight:500;margin:12px 4px">“${esc(msg)}”</p>
 <div class="row" style="justify-content:center"><button class="btn" id="bPlay" onclick="playBoost()">🔊 Hear it from Lumi</button><button class="btn ghost" onclick="boostIdx=(boostIdx||0)+1;render();setTimeout(playBoost,150)">🔀 Another one</button></div></div>
 <div class="card"><h3>🎯 Today's happy challenge</h3><div class="step"><span style="font-size:1.4em">${B.e}</span><b style="flex:1">${esc(tip)}</b><button class="btn sm" onclick="boostDone()">✅ Done</button></div></div>
 <div class="card"><h3>📅 This week's boosts</h3><div class="grid4" style="grid-template-columns:repeat(7,1fr);gap:4px">${DAY_BOOST.map((x,i)=>`<div class="center" style="padding:8px 2px;border-radius:12px;${i===new Date().getDay()?'background:var(--accent);color:#fff':'background:var(--card2)'}"><div style="font-size:1.2em">${x.e}</div><div class="tiny">${x.d.slice(0,3)}</div></div>`).join('')}</div><p class="tiny muted" style="margin:8px 0 0">Lumi has a different message for every morning, lunchtime, afternoon, evening and night of the week. Come back later for a new one!</p></div>`)}
function playBoost(){const{msg}=boostToday();const b=$('#bPlay'),av=$('#bAv'),st=$('#bSt');if(boostSpeaking){try{speechSynthesis.cancel()}catch(e){}return}
 boostSpeaking=true;if(b)b.textContent='⏹️ Stop';if(av)av.style.animation='lcTalk .5s ease-in-out infinite alternate';if(st)st.textContent='🗣️ Lumi is speaking…';
 const ok=speak(msg,'en',()=>{boostSpeaking=false;const b=$('#bPlay'),av=$('#bAv'),st=$('#bSt');if(b)b.textContent='🔊 Hear it again';if(av)av.style.animation='';if(st)st.textContent=boostToday().SL.bye});if(!ok)toast('🔇 Voice isn\'t available in this browser, but the message is right here!')}
/* rename the tab + speak automatically when opened */
const _renderAI=render_ai;render_ai=function(){_renderAI();document.querySelectorAll('#main .tabs button').forEach(b=>{if(/Mood Boost/.test(b.textContent)){b.textContent="☀️ Today's Mood Boost";b.onclick=()=>{aiTab='boost';render();setTimeout(playBoost,200)}}});const on=document.querySelector('#main .tabs button.on');if(on)on.scrollIntoView({inline:'center',block:'nearest'})};
