function loadCustomDest(){for(let i=DEST.length-1;i>=0;i--)if(DEST[i].custom)DEST.splice(i,1);(S.customDest||[]).forEach(c=>{const F=FLAGS[c.flag]||{};DEST.push({...c,custom:true,lat:F.lat??12.9,lon:F.lon??121.8,c:['#94a3b8','#64748b'],h:c.h||[],lang:c.lang||'',cur:c.cur||'',best:c.best||'',f:flagHTML(c.flag,14)})})}
