const LANG_MARK={
 Bicol:/\b(ika|dai|habo|mayo|ini|idto|saimo|sako|saako|kan|garo|ngonyan|pirmi|maray|marhay|aldaw|banggi|mamundo|kamundoan|maogma|ogma|makulog|kulog|hibi|naghihibi|mahibi|dakol|dakul|hapo|binayaan|namomotan|padaba|pagkamoot|moot|uyam|mabalos|gadan|magadan|haen|gurano|kaiba|ta ka|sinda|niato)\b/gi,
 Tagalog:/\b(ang|ng|mga|hindi|wala|ikaw|kasi|naman|lang|talaga|sobrang|ayoko|gusto|mahal|malungkot|masaya|pagod|galit|iniwan|umasa|sana|pero|bakit|akala|nasaktan|kaibigan|pala|kahit|ngayon|siya|tayo|kita|po|yung|iyak|kilig|bukas|ulit|akong|lahat|tingin|salamat|kinakabahan|natatakot|nakakainis|miss na miss)\b/gi,
 English:/\b(the|i|i'm|im|you|my|me|is|am|are|feel|feeling|but|so|was|it|and|to|of|never|always|again|why|just|really|don't|can't|love|hate)\b/gi};
function detectLang(t){const sc={};for(const k in LANG_MARK){sc[k]=(t.match(LANG_MARK[k])||[]).length}const tot=sc.Bicol+sc.Tagalog+sc.English;if(!tot)return{l:'Unknown',sc};
 const top=Object.entries(sc).sort((a,b)=>b[1]-a[1]);if(top[0][0]==='Bicol'&&sc.Bicol>=1)return{l:sc.English>=2?'Bicol + English':'Bicol',sc};if(sc.Tagalog&&sc.English&&Math.min(sc.Tagalog,sc.English)/Math.max(sc.Tagalog,sc.English)>=.34)return{l:'Taglish',sc};return{l:top[0][0],sc}}
