const HUGOT_SAMPLES2=[['English','I thought it was us, but it was only me.'],['English','You left me on seen again. 👀'],['Tagalog','Sana ako na lang ulit.'],['Tagalog','Pagod na akong umasa.'],['Tagalog','Kaibigan lang pala ang tingin mo sa akin.'],['Bicol','Mamundo ako ta binayaan mo ako.'],['Bicol','Habo ko na, hapo na ako.'],['Bicol','Maogma ako ngonyan!']];
const CRISIS_ML=/(magadan|gusto ko nang magadan|gusto kong magadan|habo ko nang mabuhay)/i;
function analyzeFeel(t){const lang=detectLang(t);const sc=FEELS.map(f=>({f,n:(t.match(f.re)||[]).length})).filter(x=>x.n);const tot=sc.reduce((a,x)=>a+x.n,0)||1;sc.sort((a,b)=>b.n-a.n);
 const neg=sc.filter(x=>!['happy','love','hope'].includes(x.f.k)).reduce((a,x)=>a+x.n,0);const hits=(t.match(HUGOT_WORDS)||[]).length;
 let score=Math.min(100,neg*16+hits*7+(sc.some(x=>x.f.k==='heart')?20:0)+(/[.…]{2,}|💔|😭|😢|\?/.test(t)?8:0)+(t.length>60?6:0));const crisis=AI_RULES[0].re.test(t)||CRISIS_ML.test(t);if(crisis)score=100;
 return{text:t,lang,feels:sc.slice(0,4).map(x=>({...x.f,p:Math.round(x.n/tot*100)})),score,crisis}}
let lastFeel=null;
aiHugot=function(tabs){setMain(tabs+`<div class="card"><h3>💔 AI Hugot & Feelings Detector</h3><p class="small muted" style="margin-top:0">Write anything in <b>English</b>, <b>Tagalog</b> or <b>Bicol</b>. Lumi will detect the language, what you're feeling, and how deep your hugot is, then give you a Support Plan.</p>
 <textarea class="f" id="hIn" rows="3" placeholder="Write how you feel… (English, Tagalog or Bicol)">${esc(lastFeel?lastFeel.text:'')}</textarea>
 <div class="tiny muted" style="margin:10px 0 6px">Quick picks</div><div class="row">${HUGOT_SAMPLES2.map(([l,s])=>`<button class="chip" style="white-space:normal;text-align:left" onclick="$('#hIn').value=this.dataset.t" data-t="${esc(s)}"><span class="tiny" style="opacity:.6;margin-right:4px">${l==='Bicol'?'BCL':l==='Tagalog'?'TL':'EN'}</span>${esc(s)}</button>`).join('')}</div>
 <button class="btn block" style="margin-top:12px" onclick="detectHugot()">🔍 Detect my feelings</button></div><div id="hOut">${lastFeel?feelHTML(lastFeel):''}</div>`)};
detectHugot=function(){const t=$('#hIn').value.trim();if(!t)return toast('Write something first.');lastFeel=analyzeFeel(t);S.hugots++;save();checkBadges();$('#hOut').innerHTML=feelHTML(lastFeel);$('#hOut').scrollIntoView({behavior:'smooth',block:'start'});
 const L=hugotLevel(lastFeel.score);const top=lastFeel.feels[0];if(S.settings.voice)speak(`${top?`I can feel that you're ${top.n.toLowerCase()}.`:''} ${L[1]}. ${L[2]}`,'en')};
function feelHTML(h){const L=hugotLevel(h.score);const top=h.feels;const plan=top.length?[...new Set(top.slice(0,2).flatMap(f=>FEEL_PLAN[f.k]))].slice(0,4):['Take 3 slow, deep breaths.','Write the full story behind your feelings in your journal.','Do one thing today that makes you smile.'];
 const pos=top.length&&['happy','love','hope'].includes(top[0].k);
 return`<div class="card"><div class="row" style="justify-content:space-between"><span class="chip">🌐 ${esc(h.lang.l==='Unknown'?'Language not sure':h.lang.l)}</span><span class="tiny muted">“${esc(h.text.slice(0,40))}${h.text.length>40?'…':''}”</span></div>
 <h3 style="margin-top:14px">🧠 What Lumi feels from you</h3>${top.length?top.map(f=>`<div class="row" style="flex-wrap:nowrap;margin:8px 0"><span style="font-size:1.4em;width:30px">${f.e}</span><span class="small" style="width:120px"><b>${f.n}</b></span><div class="bar" style="flex:1;height:10px"><i style="width:${f.p}%;background:${f.c}"></i></div><span class="tiny" style="width:38px;text-align:right">${f.p}%</span></div>`).join(''):'<p class="small muted">I couldn\'t pick up a clear feeling. Tell me a bit more?</p>'}
 ${top.length?`<p class="small" style="margin:10px 0 0">Lumi thinks you're feeling <b>${top.slice(0,2).map(f=>f.n.toLowerCase()).join(' and ')}</b>. ${pos?'I love that for you! 💛':'That’s valid, and you’re not alone. 💜'}</p>`:''}</div>
 <div class="card center"><div style="font-size:3em">${L[0]}</div><h2 style="margin:4px 0">${L[1]}</h2><div class="bar" style="height:12px;margin:10px 0"><i style="width:${h.score}%;background:linear-gradient(90deg,#60a5fa,#a78bfa,#f43f5e)"></i></div><div class="small"><b>Hugot level: ${h.score}%</b></div><p class="muted small" style="margin-bottom:0">${L[2]}</p></div>
 ${h.crisis?`<div class="card" style="border-color:var(--bad)"><h3>🆘 Important</h3><p class="small">If you're thinking about hurting yourself, please talk to someone you trust right away, or call the NCMH Crisis Hotline <b>1553</b> / <b>0917-899-8727</b>, or Hopeline PH <b>0917-558-4673</b>. Emergency: <b>911</b>.</p></div>`:''}
 <div class="card"><h3>🛟 Support Plan</h3>${plan.map((p,i)=>`<div class="step"><span class="n">${i+1}</span>${esc(p)}</div>`).join('')}<div class="row" style="margin-top:10px"><button class="btn sm" onclick="openChat()">💬 Talk to Lumi</button><button class="btn ghost sm" onclick="compose=null;initCompose();compose.text=lastFeel.text;compose.mood='${pos?'great':top[0]&&top[0].k==='angry'?'angry':top[0]&&top[0].k==='anxious'?'anxious':top[0]&&top[0].k==='tired'?'tired':'sad'}';diaryView='write';go('diary')">📝 Write it in your journal</button></div></div>`}

