function speakSoon(text,onstart,onend){
 const go=()=>{try{if(!('speechSynthesis' in window))return false;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);const v=voiceFor('en');if(v)u.voice=v;u.lang='en-US';u.rate=.98;u.pitch=1.08;u.onstart=()=>{onstart&&onstart()};u.onend=u.onerror=()=>{onend&&onend()};speechSynthesis.speak(u);return true}catch(e){return false}};
 if(S.settings.voice===false)return;go();
 setTimeout(()=>{let ok=false;try{ok=speechSynthesis.speaking||speechSynthesis.pending}catch(e){}if(!ok){const once=()=>{document.removeEventListener('pointerdown',once,true);document.removeEventListener('keydown',once,true);go()};document.addEventListener('pointerdown',once,true);document.addEventListener('keydown',once,true);setTimeout(()=>{document.removeEventListener('pointerdown',once,true);document.removeEventListener('keydown',once,true)},15000)}},450)}
