const MDB={db:null,ok:true};
function mdb(){return new Promise((res,rej)=>{if(MDB.db)return res(MDB.db);try{const r=indexedDB.open('lumi_media',1);r.onupgradeneeded=()=>r.result.createObjectStore('m');r.onsuccess=()=>{MDB.db=r.result;res(MDB.db)};r.onerror=()=>{MDB.ok=false;rej(r.error)}}catch(e){MDB.ok=false;rej(e)}})}
