function delMemMedia(mid){const m=(S.memories||[]).find(x=>x.id===mid);(m&&m.media||[]).forEach(x=>delMedia(x.id))}
function imgToBlob(file,max=1600,q=.82){return new Promise((res,rej)=>{const u=URL.createObjectURL(file);const im=new Image();im.onload=()=>{const k=Math.min(1,max/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=im.width*k;c.height=im.height*k;c.getContext('2d').drawImage(im,0,0,c.width,c.height);const t=document.createElement('canvas');const tk=Math.min(1,320/Math.max(im.width,im.height));t.width=im.width*tk;t.height=im.height*tk;t.getContext('2d').drawImage(im,0,0,t.width,t.height);URL.revokeObjectURL(u);c.toBlob(b=>res({blob:b,thumb:t.toDataURL('image/jpeg',.7)}),'image/jpeg',q)};im.onerror=()=>{URL.revokeObjectURL(u);rej(new Error('img'))};im.src=u})}
