function cgCountry(d,m){const t=[m&&m.location,m&&m.cap,d.title,d.location].filter(Boolean).join(' ');let c='';try{c=countryFromText(t)}catch(e){}
 if(!c&&d.country)c=d.country;if(c&&!FLAGS[c]){const cd=(S.customDest||[]).find(x=>x.k===c);if(cd&&FLAGS[cd.flag])c=cd.flag}return c}
