const BOOST_SLOTS={
 morning:{e:'🌅',name:'Morning',bye:'💜 Have a great day!'},
 lunch:{e:'🍱',name:'Lunchtime',bye:'🍽️ Enjoy your lunch!'},
 afternoon:{e:'🌤️',name:'Afternoon',bye:'💪 Keep going, you got this!'},
 evening:{e:'🌆',name:'Evening',bye:'🌙 Have a relaxing evening!'},
 night:{e:'🌙',name:'Night',bye:'💤 Sleep well and sweet dreams!'}};
function boostSlot(h){h=h===undefined?new Date().getHours():h;return h>=5&&h<11?'morning':h>=11&&h<14?'lunch':h>=14&&h<18?'afternoon':h>=18&&h<22?'evening':'night'}
let boostLastSlot=null;
boostToday=function(){const now=new Date();let dow=now.getDay();const slot=boostSlot(now.getHours());
 if(slot==='night'&&now.getHours()<5)dow=(dow+6)%7;   /* 1 AM Saturday still feels like Friday night */
 const B=DAY_BOOST[dow],SL=Object.assign({k:slot},BOOST_SLOTS[slot]);const pool=BOOST_MSGS[slot][dow].concat(BOOST_GEN[slot]);
 const dayNum=Math.floor((Date.now()-now.getTimezoneOffset()*6e4)/864e5);
 if(boostIdx===null||boostLastSlot!==slot){boostIdx=dayNum%2;boostLastSlot=slot}
 return{B,SL,msg:pool[boostIdx%pool.length].replace(/\{n\}/g,S.user.name.split(' ')[0]),tip:B.t[boostIdx%B.t.length]}};
/* refresh the boost page by itself when the time of day changes */
setInterval(()=>{try{if(boostLastSlot&&boostSlot()!==boostLastSlot&&typeof page!=='undefined'&&page==='ai'&&aiTab==='boost'&&!boostSpeaking)render()}catch(e){}},60000);

