function actPic(a){if(a.act&&!a.mid){const x=(S.activity||[]).find(y=>y.ts===a.ts&&y.t===a.t);if(x&&x.mid)a=Object.assign({},a,{mid:x.mid})}const r=actPic0(a);if(r.open)return r;const t=(a.t||'').toLowerCase();
 const pg=/vision board/.test(t)?'vision':/wish/.test(t)?'wishlist':/goal/.test(t)?'goals':/letter/.test(t)?'letters':/journal|entry|diary/.test(t)?'diary':/memory/.test(t)?'memories':/challenge/.test(t)?'challenges':/collection/.test(t)?'dreams':'';return Object.assign(r,pg?{open:`go('${pg}')`}:{})}
function actPic0(a){const q=(a.t||'').match(/[“"](.+?)[”"]/);const name=q?q[1]:'';let m=null;
 if(a.mid)m=(S.memories||[]).find(x=>x.id===a.mid);
 if(!m&&/^Saved memory/.test(a.t||'')){const c=(S.memories||[]).filter(x=>(x.cap||'Untitled')===name);const t=+new Date(a.ts);m=c.sort((x,y)=>Math.abs(+new Date(x.savedAt)-t)-Math.abs(+new Date(y.savedAt)-t))[0]||null}
 if(m){const v=(m.media||[]).find(x=>x.thumb);const url=m.img||m.before||(v&&v.thumb)||null;return{url,vid:!m.img&&v&&v.type==='video',open:`viewMem('${m.id}')`}}
 if(name){const d=dreams().find(x=>x.title===name);if(d)return{url:d.cover||null,open:`openDream('${d.id}')`}}return{}}
