/* Home → My Bucket List */
function showAllDreams(){dTab='list';Object.assign(dFilter,{q:'',status:'all',cat:'all',prio:'all',fav:false});go('dreams',true)}
function goDreamInList(id){showAllDreams();setTimeout(()=>{const el=document.querySelector(`#dList [onclick*="openDream('${id}')"]`);if(!el)return openDream(id);
 el.scrollIntoView({behavior:'smooth',block:'center'});el.classList.remove('dHi');void el.offsetWidth;el.classList.add('dHi');setTimeout(()=>el.classList.remove('dHi'),2600)},120)}

