const UI_EMOJI={'🪣':'list','❤️':'heart','📸':'camera','📷':'camera','🌍':'globe','🌏':'globe','🖼️':'image','💌':'mail','🕰️':'history','📊':'chart','🏆':'trophy','🎯':'target','🎉':'party','📈':'trend','🕊️':'users','🔔':'bell','⚙️':'settings','✕':'x','❓':'help','ℹ️':'info','⚠️':'alert','💬':'chat','🎨':'palette','⬇️':'download','📦':'archive','🎲':'dice','🎁':'gift','✅':'check','⏸️':'pause','⚡':'bolt','🔀':'shuffle','✏️':'edit','🗂️':'folder','🗺️':'map','✍️':'pen','📅':'calendar','📚':'bookopen','📓':'book','📒':'book','📖':'bookopen','➕':'plus','📍':'pin','✈️':'plane','🎞️':'film','☀️':'sun','🛍️':'bag','🤖':'sparkle','🏁':'flag','🌸':'flower','🫁':'wind','🫙':'jar','📞':'phone','📝':'edit','💾':'save','🎤':'mic','🗑️':'trash','⏳':'hourglass','🔇':'mute','🔊':'speaker','✓':'tick','🔎':'search','🔍':'search','⏰':'alarm','⭐':'star','🌟':'star','💜':'heart','🤍':'heart','💞':'heart','✨':'sparkle','🌌':'sparkle','🧠':'sparkle','🗣️':'voice','🕐':'clock','🕒':'clock','⏱️':'clock','🔄':'refresh','🔒':'lock','🔐':'lock','🔓':'unlock','🔑':'key','👨‍👩‍👧':'users','🚀':'rocket','📋':'clipboard','🫆':'fingerprint','🌿':'leaf','🔥':'flame','💭':'chat','🗓️':'calendar','💡':'bulb','🌐':'globe','🛰️':'globe','🏅':'medal','🌙':'moon','🔢':'hash','💔':'heartbreak','🛟':'lifebuoy','👀':'eye','👁️':'eye','🎬':'film2','📜':'scroll','📬':'mail','📧':'mail','📰':'news','📉':'trenddown','➖':'minus','☁️':'cloud','👤':'user','🛡️':'shield','↕️':'sort','🏷️':'tag','❌':'x','⏹️':'stop','⏸':'pause','🍽️':'food','💪':'bolt','💤':'moon','🧩':'grid','🧱':'grid','🎭':'sparkle','🌬️':'wind','🙋':'user','🔬':'search','🎚️':'sort','🔤':'tag','🧹':'trash','💱':'refresh','🏙️':'map','😄':'fhappy','🥰':'flove','🙂':'fsmile','😌':'fcalm','😐':'fneutral','😴':'ftired','😰':'fanxious','😢':'fsad','😠':'fangry','🏠':'house','🏫':'school','💼':'briefcase','⛪':'church','☕':'coffee','🌳':'tree','🏖️':'beach','🏥':'hospital','▶️':'play','🧗':'mountain','⛅':'partly'};
const UI_HUE={list:'#8b5cf6',heart:'#f43f5e',camera:'#f59e0b',globe:'#10b981',image:'#06b6d4',mail:'#ec4899',history:'#6366f1',chart:'#3b82f6',trophy:'#eab308',target:'#ef4444',party:'#f97316',trend:'#14b8a6',users:'#a855f7',bell:'#f43f5e',settings:'#94a3b8',help:'#60a5fa',info:'#60a5fa',alert:'#f59e0b',chat:'#8b5cf6',palette:'#ec4899',download:'#22c55e',archive:'#a78bfa',dice:'#8b5cf6',gift:'#f43f5e',check:'#22c55e',pause:'#3b82f6',x:'#94a3b8',bolt:'#f59e0b',shuffle:'#f97316',edit:'#a78bfa'};
function uiIcon(name,size,sw){return`<svg class="uic" viewBox="0 0 24 24" width="${size||22}" height="${size||22}" fill="none" stroke="currentColor" stroke-width="${sw||1.9}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${UI_ICONS[name]}</svg>`}
function emojiIcon(txt){const t=(txt||'').trim();return UI_EMOJI[t]||UI_EMOJI[t.replace(/️/g,'')]||UI_EMOJI[t+'️']||null}
/* put a tinted icon chip in place of an emoji */
function iconChip(el,size){const n=emojiIcon(el.textContent);if(!n)return;el.innerHTML=uiIcon(n,size);el.classList.add('uichip');el.style.setProperty('--hue',UI_HUE[n]||'var(--accent)')}
/* replace a leading emoji in a text button */
function iconLead(el,size){const fc=el.firstChild;if(!fc||fc.nodeType!==3)return;const m=fc.textContent.match(/^\s*(\S+)\s+/);if(!m)return;const n=emojiIcon(m[1]);if(!n)return;fc.textContent=fc.textContent.slice(m[0].length);
 const s=document.createElement('span');s.className='uilead';s.style.setProperty('--hue',UI_HUE[n]||'var(--accent)');s.innerHTML=uiIcon(n,size||18);el.insertBefore(s,fc)}
function iconLeadPlain(el,size){if(el.dataset.ic)return;const fc=el.firstChild;if(!fc||fc.nodeType!==3)return;const m=fc.textContent.match(/^\s*(\S+)\s+/);if(!m)return;const n=emojiIcon(m[1]);if(!n)return;
 fc.textContent=fc.textContent.slice(m[0].length);const sp=document.createElement('span');sp.className='uitab';sp.innerHTML=uiIcon(n,size||17,2);el.insertBefore(sp,fc);el.dataset.ic=n}
const EMO_LEAD=/^(\s*)((?:\p{Extended_Pictographic}|[✓✕➕➖])(?:️|‍\p{Extended_Pictographic}|️)*)(?=\s|$)/u;
function iconifyText(root){if(!root)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(n){const p=n.parentElement;
  if(!p||p.closest('textarea,input,select,option,script,style,svg,.bubble,.noico,[contenteditable="true"],.toastwrap'))return NodeFilter.FILTER_REJECT;return /\S/.test(n.nodeValue)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}});
 const L=[];while(w.nextNode())L.push(w.currentNode);
 L.forEach(n=>{const v=n.nodeValue;const m=v.match(EMO_LEAD);if(!m)return;const name=emojiIcon(m[2]);if(!name)return;const rest=v.slice(m[0].length);
  const sp=document.createElement('span');sp.className='uiin'+(rest.trim()?' gap':'');sp.innerHTML=uiIcon(name,null,1.9).replace(/width="\d+" height="\d+"/,'width="1.1em" height="1.1em"');
  const p=n.parentNode;p.insertBefore(sp,n);if(rest.trim())n.nodeValue=rest.replace(/^\s+/,'');else p.removeChild(n)})}
function iconifyUI(){try{document.querySelectorAll('#main .tabs button').forEach(b=>iconLeadPlain(b,17));
 const d=document.getElementById('drawer');
 if(d){d.querySelectorAll('.tile2 .ti').forEach(e=>iconChip(e,20));d.querySelectorAll('.acch .ai').forEach(e=>iconChip(e,19));d.querySelectorAll('.accb button').forEach(e=>iconLead(e,18));
  d.querySelectorAll('.mtop .ib').forEach(e=>{const n=emojiIcon(e.textContent);if(n)e.innerHTML=uiIcon(n,20)})}
 const top=document.querySelector('header.top');if(top){top.querySelectorAll('button.iconbtn').forEach(b=>{if(b.id==='backBtn')return;const fc=b.firstChild;if(fc&&fc.nodeType===3){const n=emojiIcon(fc.textContent);if(n){const w=document.createElement('span');w.className='uitop';w.innerHTML=uiIcon(n,21);b.replaceChild(w,fc)}}})}
 const main=document.getElementById('main');if(main&&page==='home'){
  main.querySelectorAll('.h2-three > button > div:first-child, .h2-two > button > div:first-child').forEach(e=>iconChip(e,22));
  main.querySelectorAll('.h2-stat .ic').forEach(e=>iconChip(e,18));
  main.querySelectorAll('.h2-act > b:first-child').forEach(e=>iconChip(e,22));
  main.querySelectorAll('.h2c h3, .card h3').forEach(e=>iconLead(e,18));
  main.querySelectorAll('.h2c button, .card button').forEach(b=>{if(b.children.length===0&&emojiIcon(b.textContent)){const n=emojiIcon(b.textContent);b.innerHTML=uiIcon(n,20);b.style.color=UI_HUE[n]}})}
  iconifyText(document.getElementById('main'));iconifyText(document.querySelector('header.top'));iconifyText(document.getElementById('drawer'));document.querySelectorAll('.modal').forEach(iconifyText);
}catch(e){}}
let _icoT=0;new MutationObserver(ms=>{if(_icoT)return;if(ms.every(m=>{const t=m.target.nodeType===1?m.target:m.target.parentElement;return !t||t.closest('#tmr,.toastwrap,.chatwin,.uiin,.uitab,.uilead')}))return;
 _icoT=requestAnimationFrame(()=>{_icoT=0;iconifyUI()})}).observe(document.body,{childList:true,subtree:true,characterData:true});
const _modalI=modal;modal=function(){const r=_modalI.apply(this,arguments);setTimeout(iconifyUI,0);return r};
const _drawMenuI=drawMenu;drawMenu=function(){_drawMenuI();iconifyUI()};
const _updateBellI=updateBell;updateBell=function(){_updateBellI();iconifyUI()};
const _renderI=render;render=function(){_renderI.apply(this,arguments);iconifyUI()};

/* leaving the app (log out, delete, lock) always closes pop-ups and the chat */
const _showWelcomeQ=showWelcome;showWelcome=function(){try{document.querySelectorAll('.modalbg').forEach(m=>m.remove())}catch(e){}try{closeChat()}catch(e){}try{closeMenu()}catch(e){}return _showWelcomeQ.apply(this,arguments)};

/* Lumi AI: one reply per message (no double sends from Enter/voice), and no double greeting */
let _chatLast={t:'',at:0};
function chatDup(t){const now=Date.now(),k=t.trim().toLowerCase();if(k&&k===_chatLast.t&&now-_chatLast.at<5000)return true;_chatLast={t:k,at:now};return false}
const _sendChatD=sendChat;
sendChat=function(preset){const inp=document.getElementById('chatIn');const t=(preset||(inp?inp.value:'')).trim();if(!t)return;
 if(document.getElementById('typ')){toast('💬 Lumi is still replying…',1500);return}
 if(chatDup(t)){if(inp)inp.value='';return}return _sendChatD(preset)};
const _cwSendD=cwSend;
cwSend=function(preset){const inp=document.getElementById('cwI');const t=(preset||(inp?inp.value:'')).trim();if(!t)return;
 if(document.getElementById('cwTyp')){toast('💬 Lumi is still replying…',1500);return}
 if(chatDup(t)){if(inp)inp.value='';return}return _cwSendD(preset)};
const GREET_RE=/^\s*(hey|hi|hello|yay|aww|kumusta|uy|hoy|good to see you|welcome back|welcome|good morning|good afternoon|good evening)\b[^!?.]{0,30}[!?.]+\s*(\p{Extended_Pictographic}️?\s*)*/iu;
const _aiReplyD=aiReply;
aiReply=function(t){const nm=((S.user&&S.user.name)||'').split(' ')[0];
 if(/\b(i love you|love you|mahal kita|lab yu)\b/i.test(t))return{text:`Aww, I love you too, ${nm}! 💜 Thank you for letting me be part of your journey.`,lang:'en'};
 if(/\b(good ?night|tulog na|matutulog na|sleep na)\b/i.test(t))return{text:`Good night, ${nm}! 🌙 Rest well. Your dreams will still be here tomorrow, waiting for you.`,lang:'en'};
 const r=_aiReplyD(t);try{const ai=(S.chat||[]).filter(c=>!c.me);const prev=ai.length?ai[ai.length-1].t:'';
 if(r&&r.text&&GREET_RE.test(prev)&&GREET_RE.test(r.text)&&!/^\s*yay/i.test(r.text)){let x=r.text.replace(GREET_RE,'').trim();if(x.length>8){x=x.charAt(0).toUpperCase()+x.slice(1);r.text=x}}}catch(e){}return r};

/* AI answers can have simple formatting: **bold**, lists, `code` and ```code blocks``` */
function fmtAI(t){t=String(t||'');const blocks=[];t=t.replace(/```[a-zA-Z0-9+#-]*\n?([\s\S]*?)```/g,(m,c)=>{blocks.push(c.replace(/\n$/,''));return '\u0000'+(blocks.length-1)+'\u0000'});
 let h=esc(t);h=h.replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\*\*([^*\n]+)\*\*/g,'<b>$1</b>').replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g,'$1<i>$2</i>');
 const lines=h.split('\n');let out='',list='';
 lines.forEach(l=>{const ol=l.match(/^\s*(\d+)[.)]\s+(.*)$/),ul=l.match(/^\s*[-*•]\s+(.*)$/),hd=l.match(/^\s*#{1,4}\s+(.*)$/);
  if(ol){if(list!=='ol'){out+=(list?`</${list}>`:'')+'<ol>';list='ol'}out+=`<li>${ol[2]}</li>`;return}
  if(ul){if(list!=='ul'){out+=(list?`</${list}>`:'')+'<ul>';list='ul'}out+=`<li>${ul[1]}</li>`;return}
  if(list){out+=`</${list}>`;list=''}
  if(hd){out+=`<b class="aih">${hd[1]}</b>`;return}
  out+=l.trim()===''?'<br>':l+'<br>'});
 if(list)out+=`</${list}>`;out=out.replace(/(<br>)+$/,'').replace(/(<br>){3,}/g,'<br><br>');
 return out.replace(/\u0000(\d+)\u0000(<br>)?/g,(m,i)=>`<pre class="aicode"><button class="aicopy" onclick="navigator.clipboard&&navigator.clipboard.writeText(this.nextElementSibling.textContent);toast('📋 Code copied')">Copy</button><code>${esc(blocks[+i])}</code></pre>`)}
function mdPlain(t){return String(t||'').replace(/```[\s\S]*?```/g,' (code on screen) ').replace(/`([^`]+)`/g,'$1').replace(/\*\*?([^*]+)\*\*?/g,'$1').replace(/^\s*#{1,4}\s+/gm,'').replace(/^\s*[-*•]\s+/gm,'').replace(/\n+/g,'. ')}
const _speakMD=speak;speak=function(t,...a){return _speakMD(mdPlain(t),...a)};

